import {p,n,w,mathematicalResult,c,meta,build,review,inquiry,choose,factorial,clean} from './advanced-authoring.mjs';

const eq=(en,zh,expression,result,strategy,bridge,derivation,why)=>mathematicalResult(w(en,zh,expression,p(result,result),strategy,bridge,derivation,why),result);
const V=p('Use vector components and the distributive laws.','使用向量分量及分配律。');
const D=p('Use the dot product to connect coordinates with length or angle.','用內積連結座標與長度或角度。');
const A=p('Translate the geometric condition into a coordinate equation.','把幾何條件轉成座標方程。');
const C=p('Complete squares before reading the geometric parameters.','先配方，再讀取幾何參數。');
const entries=[];
const add=(m,bank)=>{ m.inquiry.type=({'1':'vectors','2':'conics','3':'conics','4':'sequences','5':'calculus','6':'probability','7':'probability','8':'statistics'})[m.chapterId.split('-')[1]]; entries.push({id:m.id,meta:m,bank}); };
const probe=(en,zh,changedEn,changedZh)=>inquiry('predict-compare-explain',en,zh,'Calculate two valid cases and explain the change using the defining relation.','計算兩個符合條件的例子，利用定義關係解釋變化。',changedEn,changedZh);

export const advancedChapters=[
 {id:'s1-1',bookId:'s1',number:1,title:p('Space vectors and solid geometry','空間向量與立體幾何')},
 {id:'s1-2',bookId:'s1',number:2,title:p('Equations of lines and circles','直線和圓的方程')},
 {id:'s1-3',bookId:'s1',number:3,title:p('Conic sections','圓錐曲線的方程')},
 {id:'s2-4',bookId:'s2',number:4,title:p('Sequences','數列')},
 {id:'s2-5',bookId:'s2',number:5,title:p('Derivatives and their applications','一元函數的導數及其應用')},
 {id:'s3-6',bookId:'s3',number:6,title:p('Counting principles','計數原理')},
 {id:'s3-7',bookId:'s3',number:7,title:p('Random variables and distributions','隨機變量及其分佈')},
 {id:'s3-8',bookId:'s3',number:8,title:p('Statistical analysis of paired data','成對數據的統計分析')},
];

add(meta('s1-1-1',p('Space vectors and their operations','空間向量及其運算'),2,p('Add, scale and multiply space vectors; distinguish scalar and vector results.','對空間向量作加法、數乘及內積，區分純量與向量結果。'),[
 c('Operations','運算','Addition and scaling act component by component.','加法及數乘逐一作用於各分量。','a+b=(a_1+b_1,a_2+b_2,a_3+b_3)'),
 c('Angle conditions','角度條件','The angle formula requires two nonzero vectors; a dot product is a scalar.','角度公式須用兩個非零向量；內積的結果為純量。','\\cos\\theta=\\frac{a\\cdot b}{|a||b|}')
],[p('A zero dot product indicates perpendicular directions only when both vectors are nonzero.','內積為零只有在兩向量非零時才能表示方向垂直。')],['c2-6-2'],probe('Predict which changes affect length but preserve direction.','預測哪些變化會改變長度而保留方向。','Compare multiplication by a positive, negative and zero scalar.','比較正數、負數及零的數乘。')),(k,t)=>{
 if(k===0)return n('Find the first component of a+b.','求 a+b 的第一分量。',`a=(${t},2,-1),\\quad b=(3,-2,4)`,t+3,V,'(a+b)_1=a_1+b_1',[`(a+b)=(${t+3},0,3)`],p('Cancellation of other components does not affect the first component.','其他分量相消不影響第一分量。'));
 if(k===1)return n('Find the third component of 2a−3b.','求 2a−3b 的第三分量。',`a=(1,${t},-2),\\quad b=(2,0,${t})`,-4-3*t,V,'(2a-3b)_3=2a_3-3b_3',[`2(-2)-3(${t})=${-4-3*t}`],p('Scale each entire vector before subtracting.','先對整個向量數乘，再相減。'));
 if(k===2)return n('Find the squared length of a.','求 a 的長度平方。',`a=(${t},2,3)`,t*t+13,D,'|a|^2=a\\cdot a',[`|a|^2=${t}^2+2^2+3^2=${t*t+13}`],p('Length squared is the sum of component squares.','長度平方等於各分量平方之和。'));
 if(k===3)return n('Calculate a·b.','計算 a·b。',`a=(${t},1,2),\\quad b=(2,-3,1)`,2*t-1,D,'a\\cdot b=a_1b_1+a_2b_2+a_3b_3',[`a\\cdot b=2(${t})-3+2=${2*t-1}`],p('A dot product is a signed scalar, not a vector.','內積是帶正負號的純量，不是向量。'));
 if(k===4)return n('Find cos θ between a and b.','求 a 與 b 夾角的 cos θ。',`a=(${t},0,0),\\quad b=(${t},${t},0)`,1/Math.sqrt(2),D,'\\cos\\theta=(a\\cdot b)/(|a||b|)',[`a\\cdot b=${t*t},\\quad |a|=${t},\\quad |b|=${t}\\sqrt2`,`\\cos\\theta=1/\\sqrt2`],p('A common positive scale cancels in the angle formula.','共同的正比例因子會在角度公式中約去。'));
 if(k===5)return eq('Are a and b parallel? Justify your answer.','a 與 b 是否平行？說明理由。',`a=(1,2,${t}),\\quad b=(2,4,${2*t})`,'b=2a',V,'b=\\lambda a',[`(2,4,${2*t})=2(1,2,${t})`],p('All components have the same scalar multiplier.','所有分量均有相同的數乘因子。'));
 return n('Three mutually perpendicular edges have lengths t,3,4. Find the squared space diagonal.','三條互相垂直的邊長為 t、3、4。求體對角線長度平方。',`t=${t}`,t*t+25,D,'|u+v+w|^2=|u|^2+|v|^2+|w|^2',[`u\\cdot v=u\\cdot w=v\\cdot w=0`,`d^2=${t}^2+3^2+4^2=${t*t+25}`],p('Orthogonality removes all cross terms.','互相垂直使所有交叉項為零。'));
});

add(meta('s1-1-2',p('The fundamental theorem of space vectors','空間向量基本定理'),11,p('Recognise a basis and use unique vector coordinates and affine combinations.','辨認基底，運用向量座標的唯一性及仿射組合。'),[
 c('Basis','基底','Three noncoplanar vectors span space uniquely.','三個不共面的向量可唯一表示空間中的每個向量。','v=xe_1+ye_2+ze_3'),
 c('Independence and affine points','獨立性與仿射點','A basis must be independent. Weights representing a point in a plane sum to one.','基底必須線性獨立；用平面上的點作仿射組合時，權重之和須為一。')
],[p('Three vectors are not automatically a basis merely because there are three of them.','不是任意三個向量都能組成基底。')],['s1-1-1'],probe('Can three nonzero vectors still fail to describe all space?','三個非零向量仍可能無法描述整個空間嗎？','Construct a dependent triple and two different representations of the same vector.','構造一組相依向量，並用兩種不同方式表示同一向量。')),(k,t)=>{
 if(k===0)return n('In the standard basis, find the coefficient of e3.','在標準基底中，求 e3 的係數。',`v=2e_1-e_2+${t}e_3`,t,V,'v=(x,y,z)',[`(x,y,z)=(2,-1,${t})`],p('A basis coefficient is a coordinate relative to that basis.','基底係數是相對該基底的座標。'));
 if(k===1)return n('Find the coefficient of e1 when e1=(1,0,0), e2=(1,1,0), e3=(0,0,1).','當 e1=(1,0,0)、e2=(1,1,0)、e3=(0,0,1) 時，求 v 的 e1 係數。',`v=(${t+2},2,3)`,t,V,'(x+y,y,z)=v',[`y=2,\\quad z=3,\\quad x=${t+2}-2=${t}`],p('Changing the basis changes coefficients even when the geometric vector is unchanged.','幾何向量不變，換基底仍會改變其係數。'));
 if(k===2)return eq('Decide whether e1,e2,e3 form a basis.','判斷 e1、e2、e3 是否為基底。',`e_1=(1,0,0),\\ e_2=(0,1,0),\\ e_3=(${t},2,0)`,`e_3=${t}e_1+2e_2`,V,'All third components are zero.',[`e_3=${t}e_1+2e_2`],p('They span only a plane and cannot represent (0,0,1).','它們只張成一個平面，不能表示 (0,0,1)。'));
 if(k===3)return n('Find λ so that the third vector lies in the plane spanned by the first two.','求 λ，使第三向量位於前兩向量張成的平面。',`a=(1,0,0),\\ b=(0,1,0),\\ c=(${t},2,\\lambda)`,0,V,'c=xa+yb',[`c=(x,y,0)\\Rightarrow\\lambda=0`],p('The plane spanned by a and b has zero third coordinate.','a、b 張成的平面之第三座標為零。'));
 if(k===4)return n('P=αA+βB+γC is affine, α=1/(t+1), β=1/2. Find γ.','P=αA+βB+γC 為仿射組合，α=1/(t+1)、β=1/2。求 γ。',`t=${t}`,0.5-1/(t+1),A,'α+β+γ=1',[`\\gamma=1-1/${t+1}-1/2`],p('Affine weights sum to one.','仿射權重之和為一。'));
 if(k===5)return eq('Find the representation of v in the given basis.','用所給基底表示 v。',`e_1=(1,1,0),\\ e_2=(1,-1,0),\\ e_3=(0,0,1),\\ v=(${2*t},2,3)`,`v=${t+1}e_1+${t-1}e_2+3e_3`,V,'x+y=2t,\\quad x-y=2',[`2x=${2*t+2}\\Rightarrow x=${t+1}`,`y=${t-1},\\quad z=3`],p('Solve the simultaneous component equations; uniqueness follows from independence.','聯立分量方程求解；獨立性保證表示唯一。'));
 return eq('Explain why these three vectors do not give unique coefficients.','說明這三個向量為何不能給出唯一係數。',`e_1=(1,0,0), e_2=(0,1,0), e_3=(${t},1,0)`,`e_3=${t}e_1+e_2`,V,'e_3=te_1+e_2',[`(${t},1,0)=${t}(1,0,0)+(0,1,0)`],p('The dependent triple permits more than one representation.','相依的三向量容許不止一種表示。'));
});

add(meta('s1-1-3',p('Coordinate representation of space vectors','空間向量及其座標表示'),16,p('Calculate spatial lengths, angles, projections and perpendicular directions from coordinates.','利用座標計算空間長度、角度、投影及垂直方向。'),[
 c('Coordinates','座標','Subtract point coordinates to obtain a displacement vector.','以終點座標減起點座標，得到位移向量。','\\overrightarrow{AB}=B-A'),
 c('Projection conditions','投影條件','Projection requires a nonzero direction; signed scalar projection can be negative.','投影方向須非零；有向純量投影可以是負數。','\\operatorname{proj}_{u}v=\\frac{v\\cdot u}{u\\cdot u}u')
],[p('A projection vector and its signed scalar component are different objects.','投影向量與其有向純量分量是不同概念。')],['s1-1-1','s1-1-2'],probe('Predict what happens to projection when the direction vector is reversed.','預測反轉方向向量後，投影會怎樣改變。','Compare the projection vector and signed component under u→−u.','比較 u→−u 時的投影向量及有向分量。')),(k,t)=>{
 if(k===0)return n('Find AB².','求 AB²。',`A=(1,2,3),\\ B=(${t+1},5,7)`,t*t+25,D,'AB^2=(B-A)\\cdot(B-A)',[`B-A=(${t},3,4)`,`AB^2=${t*t}+9+16=${t*t+25}`],p('Distance uses the displacement, not either point vector alone.','距離使用位移向量，不是單獨的點向量。'));
 if(k===1)return n('Find the z-coordinate of the midpoint of A and B.','求 A、B 中點的 z 座標。',`A=(1,2,${t}),\\ B=(3,4,${t+6})`,t+3,A,'M=(A+B)/2',[`M_z=(${t}+${t+6})/2=${t+3}`],p('Midpoint averaging applies separately to all three coordinates.','中點公式對三個座標分別取平均。'));
 if(k===2)return n('Find λ so that a and b are perpendicular.','求 λ，使 a 與 b 垂直。',`a=(1,2,3),\\ b=(${t},1,\\lambda)`,-(t+2)/3,D,'a\\cdot b=0',[`${t}+2+3\\lambda=0`,`\\lambda=-${t+2}/3`],p('Use a zero dot product, not componentwise multiplication equal to zero.','使用內積為零，不能要求每個分量的乘積都為零。'));
 if(k===3)return n('Find cos θ between a and b.','求 a 與 b 夾角的 cos θ。',`a=(1,1,0), b=(0,${t},1)`,t/Math.sqrt(2*(t*t+1)),D,'cosθ=(a·b)/(|a||b|)',[`a\\cdot b=${t}, |a|=\\sqrt2, |b|=\\sqrt{${t*t+1}}`,`\\cos\\theta=${t}/\\sqrt{${2*(t*t+1)}}`],p('Both vector lengths enter the denominator.','分母須包含兩個向量長度。'));
 if(k===4)return n('Find the signed scalar projection of v onto u.','求 v 在 u 方向的有向純量投影。',`v=(${t},2,0),\\ u=(1,0,0)`,t,D,'s=v\\cdot u/|u|',[`s=${t}/1=${t}`],p('A unit coordinate direction picks out the matching component.','單位座標方向會取出對應分量。'));
 if(k===5)return n('A unit direction has cos²α=1/t², cos²β=1/9. Find cos²γ.','單位方向有 cos²α=1/t²、cos²β=1/9。求 cos²γ。',`t=${t}`,8/9-1/(t*t),D,'cos²α+cos²β+cos²γ=1',[`\\cos^2\\gamma=1-1/${t*t}-1/9`],p('The squared direction cosines sum to one.','方向餘弦平方之和為一。'));
 return eq('Find a nonzero vector perpendicular to both a and b, with third component 1.','求同時垂直於 a、b 的非零向量，且第三分量為1。',`a=(1,0,${t}),\\ b=(0,1,2)`,`u=(-${t},-2,1)`,D,'u\\cdot a=u\\cdot b=0',[`x+${t}z=0,\\quad y+2z=0`,`z=1\\Rightarrow x=-${t},\\ y=-2`],p('Two linear constraints determine a perpendicular direction up to scale.','兩個線性條件決定垂直方向，仍可作非零數乘。'));
});

add(meta('s1-1-4',p('Applications of space vectors','空間向量的應用'),26,p('Use direction and normal vectors to establish angles, distances and spatial relations.','用方向及法向量建立角度、距離及空間位置關係。'),[
 c('Normals','法向量','A plane normal is perpendicular to every direction in the plane.','平面的法向量垂直於平面內所有方向。','n\\cdot(X-P)=0'),
 c('Angles and distance','角度與距離','Use acute line/plane angles; normals must be nonzero and distances nonnegative.','直線、平面的夾角取銳角或直角；法向量須非零，距離非負。','d=\\frac{|n\\cdot(P-P_0)|}{|n|}')
],[p('The line-plane angle is complementary to the angle between the line direction and plane normal.','直線與平面的夾角，與直線方向及平面法向量的夾角互餘。')],['s1-1-3'],probe('Predict whether translating a plane changes its direction or its distance from a fixed point.','預測平移平面會否改變方向，或改變它與固定點的距離。','Compare parallel planes with the same normal but different constants.','比較具有相同法向量而常數不同的平行平面。')),(k,t)=>{
 if(k===0)return n('Find the cosine of the acute angle between the lines.','求兩直線銳角的餘弦。',`u=(1,0,0), v=(1,${t},0)`,1/Math.sqrt(1+t*t),D,'cosθ=|u·v|/(|u||v|)',[`\\cos\\theta=1/\\sqrt{${1+t*t}}`],p('The absolute dot product selects the acute line angle.','內積取絕對值給出銳角。'));
 if(k===1)return n('Find sin α for the angle of the line with the plane.','求直線與平面夾角 α 的 sin α。','u=(1,0,1),\\quad \\Pi:z=0',1/Math.sqrt(2),D,'\\sin\\alpha=|u\\cdot n|/(|u||n|)',['n=(0,0,1)','\\sin\\alpha=1/\\sqrt2'],p('Use sine for the line-plane angle because the normal angle is its complement.','平面法向量所成角互餘，因此直線與平面夾角使用正弦。'));
 if(k===2)return n('Find the cosine of the acute angle between the planes.','求兩平面銳角的餘弦。','n_1=(1,1,0),\\quad n_2=(0,1,1)',0.5,D,'\\cos\\theta=|n_1\\cdot n_2|/(|n_1||n_2|)',['n_1\\cdot n_2=1','\\cos\\theta=1/2'],p('The angle between normals determines the acute plane angle.','法向量夾角決定兩平面的銳角。'));
 if(k===3)return n('Find the distance from P to the plane.','求 P 到平面的距離。',`P=(0,0,${t}),\\quad \\Pi:z=2`,Math.abs(t-2),D,'d=|z_P-2|',[`d=|${t}-2|=${Math.abs(t-2)}`],p('The normal displacement gives the shortest distance.','法向位移給出最短距離。'));
 if(k===4)return n('Find the distance from P to the plane.','求 P 到平面的距離。',`P=(${t},0,0),\\quad \\Pi:3x+4y=0`,3*t/5,D,'d=|3x_P+4y_P|/5',[`d=3(${t})/\\sqrt{3^2+4^2}=${3*t/5}`],p('Normalize the plane normal; raw substitution is not a distance.','須除以法向量長度，直接代入的值不是距離。'));
 if(k===5)return eq('Does the entire line lie in the plane?','整條直線是否位於此平面？',`X=(0,0,${t})+s(1,-1,0), \\Pi:x+y+z=${t}`,'\\ell\\subset\\Pi',D,'n·u=0 and the initial point is in the plane.',[`x+y+z=s-s+${t}=${t}`],p('Direction parallelism plus an incident point proves containment.','方向平行，加上有一點在平面上，可證明包含關係。'));
 return eq('Find the plane through P with normal n.','求通過 P 且法向量為 n 的平面。',`P=(1,2,${t}),\\quad n=(2,-1,3)`,`2x-y+3z=${3*t}`,A,'n\\cdot(X-P)=0',[`2(x-1)-(y-2)+3(z-${t})=0`,`2x-y+3z=${3*t}`],p('The constant depends on the point; the coefficients specify the normal.','常數由通過的點決定；各係數構成法向量。'));
});

add(meta('s1-2-1',p('Inclination and slope of a line','直線的傾斜角與斜率'),51,p('Connect slope, inclination and parallel/perpendicular directions, including vertical lines.','連結斜率、傾斜角及平行垂直方向，並處理鉛直直線。'),[
 c('Slope','斜率','For a nonvertical line, slope is rise divided by run and equals tan of the inclination.','非鉛直直線的斜率為縱向變化除以橫向變化，等於傾斜角的正切。','m=(y_2-y_1)/(x_2-x_1)'),
 c('Exceptional directions','特殊方向','A vertical line has no finite slope; m1m2=−1 applies only when both slopes exist.','鉛直直線没有有限斜率；m1m2=−1 只在兩個斜率均存在時適用。')
],[p('A vertical line is perpendicular to a horizontal line even though its slope is undefined.','鉛直線與水平線垂直，雖然鉛直線斜率未定義。')],['c1-4-1'],probe('Does a steeper line always have a larger slope?','越陡的直線是否總有較大的斜率？','Compare positive and negative slopes and the vertical limiting case.','比較正斜率、負斜率及接近鉛直的情況。')),(k,t)=>{
 if(k===0)return n('Find the slope of AB.','求 AB 的斜率。',`A=(1,2),\\ B=(3,${2*t+2})`,t,A,'m=\\Delta y/\\Delta x',[`m=(${2*t+2}-2)/(3-1)=${t}`],p('Use consistent order in numerator and denominator.','分子分母必須使用一致的兩點次序。'));
 if(k===1)return n('A line has inclination 135°. Find its slope.','直線傾斜角為135°。求斜率。','m=\\tan135^\\circ',-1,A,'\\tan(180^\\circ-45^\\circ)=-\\tan45^\\circ',['m=-1'],p('Inclination lies in [0°,180°); a second-quadrant angle has negative tangent.','傾斜角在 [0°,180°)；第二象限的正切為負。'));
 if(k===2)return eq('Describe the inclination and slope of the line.','描述此直線的傾斜角及斜率。',`x=${t}`,'\\alpha=90^\\circ;\\quad m\\text{ undefined}',A,'\\Delta x=0',['m=\\Delta y/0\\text{ is not defined}'],p('Do not replace an undefined slope by the number infinity.','不要把未定義的斜率當作數值無窮大。'));
 if(k===3)return n('Find the slope of a line perpendicular to y=tx+1.','求垂直於 y=tx+1 的直線斜率。',`t=${t}`,-1/t,A,'m_1m_2=-1',[`m_2=-1/${t}`],p('The given slope is nonzero, so the negative reciprocal rule applies.','所給斜率非零，可以使用負倒數法則。'));
 if(k===4)return n('Find a so that the two nonvertical lines are parallel.','求 a，使兩條非鉛直直線平行。',`y=(2a+1)x+3,\\quad y=${2*t+1}x-1`,t,A,'2a+1=2t+1',[`2a+1=${2*t+1}\\Rightarrow a=${t}`],p('Different intercepts ensure distinct parallel lines once slopes match.','斜率相同且截距不同，保證為兩條相異平行線。'));
 if(k===5)return n('Find the tangent of the acute angle between slopes 0 and t.','求斜率為0及 t 的兩直線銳角之正切。',`t=${t}`,t,A,'\\tan\\theta=|(m_2-m_1)/(1+m_1m_2)|',[`\\tan\\theta=|(${t}-0)/(1+0)|=${t}`],p('The denominator is nonzero here; perpendicular lines require separate handling.','此題分母非零；垂直直線須另行處理。'));
 return eq('Lines through O meet the segment from A=(t,1) to B=(t,3). Find the slope range.','通過 O 的直線與 A=(t,1)、B=(t,3) 的線段相交。求斜率範圍。',`t=${t}`,`\\frac1{${t}}\\le m\\le\\frac3{${t}}`,A,'y=mt,\\quad 1\\le y\\le3',[`1\\le ${t}m\\le3`,`1/${t}\\le m\\le3/${t}`],p('A segment gives a closed range; replacing it by the full supporting line would change the answer.','線段給出閉區間；若改成整條支撐直線，答案會改變。'));
});

add(meta('s1-2-2',p('Equations of a line','直線的方程'),59,p('Choose point-slope, two-point, intercept or general form without losing exceptional lines.','選擇點斜式、兩點式、截距式或一般式，避免漏掉特殊直線。'),[
 c('General form','一般式','Ax+By+C=0 represents a line when A and B are not both zero.','A、B 不同時為零時，Ax+By+C=0 表示直線。','A(x-x_0)+B(y-y_0)=0'),
 c('Form restrictions','形式限制','Point-slope form omits vertical lines; intercept form requires nonzero intercepts.','點斜式不包含鉛直線；截距式要求兩截距非零。')
],[p('Dividing an equation by a parameter can silently delete a valid line.','用參數除方程可能無意中刪去有效直線。')],['s1-2-1'],probe('Which common forms can describe a line through the origin or a vertical line?','哪些常用形式能描述通過原點或鉛直的直線？','Compare equivalent forms and identify where division excludes a case.','比較等價形式，指出除法排除了哪些情況。')),(k,t)=>{
 if(k===0)return eq('Find the line through (2,3) with slope t.','求通過 (2,3) 且斜率為 t 的直線。',`t=${t}`,`y-3=${t}(x-2)`,A,'y-y_0=m(x-x_0)',[`y-3=${t}(x-2)`],p('Substitution of the given point checks the constant.','代入所給點可檢查常數。'));
 if(k===1)return eq('Find the line through (t,1) and (t,5).','求通過 (t,1)、(t,5) 的直線。',`t=${t}`,`x=${t}`,A,'x_1=x_2',[`x=${t}`],p('Use a vertical equation directly instead of dividing by zero in a slope formula.','直接使用鉛直線方程，避免在斜率公式中除以零。'));
 if(k===2)return n('Find the y-intercept of the line with x-intercept t and passing through (0,4).','直線的 x 截距為 t，且通過 (0,4)。求 y 截距。',`t=${t}`,4,A,'x/t+y/b=1',['(0,4)\\Rightarrow4/b=1\\Rightarrow b=4'],p('An intercept is a signed coordinate, not a distance.','截距是帶正負號的座標，不是距離。'));
 if(k===3)return n('Find C so that Ax+By+C=0 passes through P.','求 C，使 Ax+By+C=0 通過 P。',`A=2,\\ B=-3,\\ P=(${t},1)`,3-2*t,A,'C=-Ax_P-By_P',[`C=-2(${t})+3=${3-2*t}`],p('A point satisfies the equation exactly when the substituted expression is zero.','點在直線上，等價於代入後的式子為零。'));
 if(k===4)return eq('Find the perpendicular bisector of (0,0) and (2t,0).','求 (0,0)、(2t,0) 的垂直平分線。',`t=${t}`,`x=${t}`,A,'M=(t,0),\\quad AB\\text{ horizontal}',[`M=(${t},0)`,`x=${t}`],p('The perpendicular bisector consists of points equidistant from the two endpoints.','垂直平分線由到兩端點距離相同的點組成。'));
 if(k===5)return eq('Find the reflection of the line in the y-axis.','求直線關於 y 軸的對稱直線。',`y=${t}x+2`,`y=-${t}x+2`,A,'x\\mapsto-x',[`y=${t}(-x)+2=-${t}x+2`],p('Reflection changes the x-coordinate sign while leaving y unchanged.','關於 y 軸對稱會反轉 x 座標的正負，保留 y 座標。'));
 return eq('Find the fixed point shared by this line family.','求此直線族共同通過的固定點。',`(x-${t})+\\lambda(y-${2*t})=0`,`P=(${t},${2*t})`,A,'Both the constant part and parameter coefficient vanish.',[`x=${t}, y=${2*t}`],p('The point works for every real parameter.','此點適用於每個實參數。'));
});

add(meta('s1-2-3',p('Intersections and distance formulas','直線的交點座標與距離公式'),70,p('Solve intersections and calculate point-line and parallel-line distances with geometric checks.','求直線交點，計算點到直線及平行直線距離，並作幾何檢查。'),[
 c('Intersection','交點','Solve both linear equations simultaneously and check both.','聯立兩條線性方程求解，再代入兩式檢查。'),
 c('Normalized distance','正規化距離','The denominator is the norm of the normal vector; parallel-line formulas require matched coefficients.','分母是法向量長度；平行線距離公式要求係數先化成一致。','d=|Ax_0+By_0+C|/\\sqrt{A^2+B^2}')
],[p('Subtracting constants before matching parallel-line coefficients gives a wrong distance.','未統一平行線係數便相減常數，會得到錯誤距離。')],['s1-2-2'],probe('Why does multiplying a line equation by 100 leave its distance formula unchanged?','把直線方程乘以100，為甚麼距離不變？','Test invariance under positive and negative scaling of the equation.','檢驗方程作正數及負數倍數後的距離。')),(k,t)=>{
 if(k===0)return n('Find the x-coordinate of the intersection.','求交點的 x 座標。',`x+y=${2*t},\\quad x-y=2`,t+1,A,'2x=2t+2',[`2x=${2*t+2}\\Rightarrow x=${t+1}`],p('Adding eliminates y; subtraction finds y if needed.','兩式相加消去 y；若需要，可相減求 y。'));
 if(k===1)return n('Find the distance from (0,0) to x=t.','求 (0,0) 到 x=t 的距離。',`t=${t}`,t,A,'d=|0-t|',[`d=${t}`],p('The shortest segment is horizontal.','最短線段為水平線段。'));
 if(k===2)return n('Find the distance from P to the line.','求 P 到直線的距離。',`P=(0,0),\\quad 3x+4y-${5*t}=0`,t,A,'d=|C|/5',[`d=${5*t}/\\sqrt{9+16}=${t}`],p('The normal (3,4) has length 5.','法向量 (3,4) 的長度為5。'));
 if(k===3)return n('Find the distance between the parallel lines.','求兩條平行直線的距離。',`3x+4y=0,\\quad 6x+8y=${10*t}`,t,A,'3x+4y=5t',[`d=|${5*t}-0|/5=${t}`],p('Divide the second equation by two before comparing constants.','先把第二式除以二，才比較常數。'));
 if(k===4)return eq('Find the foot of the perpendicular from P to the line.','求 P 到直線的垂足。',`P=(${t},2),\\quad y=x`,`H=(${(t+2)/2},${(t+2)/2})`,A,'H=(h,h),\\quad(P-H)\\cdot(1,1)=0',[`${t}+2-2h=0`,`h=${(t+2)/2}`],p('A foot lies on the line and its displacement from P is perpendicular to the line.','垂足在直線上，且與 P 的位移垂直於直線。'));
 if(k===5)return eq('Reflect P in the line y=x.','求 P 關於 y=x 的對稱點。',`P=(${t},2)`,`P'=(2,${t})`,A,'P+P\\prime=2H',[`H=(${(t+2)/2},${(t+2)/2})`,`P'=2H-P=(2,${t})`],p('Reflection across y=x swaps coordinates.','關於 y=x 對稱會交換兩個座標。'));
 return n('A=(0,1), B=(t,3), P is on y=0. Find the minimum of AP+PB.','A=(0,1)、B=(t,3)，P 在 y=0 上。求 AP+PB 的最小值。',`t=${t}`,Math.sqrt(t*t+16),A,'Reflect A to A\\prime=(0,-1).',[`AP=A'P`,`AP+PB\\ge A'B=\\sqrt{${t}^2+4^2}`],p('The segment A′B crosses y=0, so equality is attainable.','線段 A′B 穿過 y=0，因此等號可成立。'));
});

add(meta('s1-2-4',p('Equations of a circle','圓的方程'),82,p('Construct circle equations from centers, radii, diameters and point constraints.','由圓心、半徑、直徑及點的條件建立圓的方程。'),[
 c('Standard form','標準式','A circle is the locus at fixed positive distance from its center.','圓是與圓心相距固定正距離的點的軌跡。','(x-h)^2+(y-k)^2=r^2'),
 c('Existence','存在條件','In x²+y²+Dx+Ey+F=0, a nondegenerate circle requires (D²+E²)/4−F>0.','在一般式中，非退化圓要求 (D²+E²)/4−F>0。')
],[p('A positive squared radius is necessary; zero gives a single point, and negative gives no real locus.','半徑平方須為正；零表示單點，負數表示沒有實點軌跡。')],['s1-2-3'],probe('Predict the shape when the constant of a circle equation changes through the zero-radius threshold.','預測常數穿過零半徑臨界值時，圓方程的圖形怎樣改變。','Compare a circle, a point and an empty real locus by completing squares.','用配方比較圓、單點及沒有實點的軌跡。')),(k,t)=>{
 if(k===0)return n('Find the radius of the circle.','求圓的半徑。',`(x-2)^2+(y+1)^2=${t*t}`,t,C,'r^2=t^2',[`r=\\sqrt{${t*t}}=${t}`],p('The radius is the positive square root.','半徑取正平方根。'));
 if(k===1)return n('Find the x-coordinate of the center.','求圓心的 x 座標。',`x^2+y^2-${2*t}x+4y+1=0`,t,C,'x^2-2tx=(x-t)^2-t^2',[`(x-${t})^2+(y+2)^2=${t*t+3}`],p('The center has the opposite signs from the offsets inside the squares.','圓心座標的符號與平方括號內的平移量相反。'));
 if(k===2)return n('Find the squared radius of the circle with diameter endpoints A and B.','求以 A、B 為直徑端點的圓之半徑平方。',`A=(0,0),\\quad B=(${2*t},4)`,t*t+4,A,'r^2=AB^2/4',[`AB^2=(2\\cdot${t})^2+4^2`,`r^2=${t*t+4}`],p('The radius is half the diameter, so its square is one quarter.','半徑為直徑的一半，因此平方為四分之一。'));
 if(k===3)return eq('Find the circle centered at (t,−1) and passing through (t+3,3).','求圓心為 (t,−1) 且通過 (t+3,3) 的圓。',`t=${t}`,`(x-${t})^2+(y+1)^2=25`,A,'r^2=3^2+4^2',['r^2=25'],p('Use the center-to-point distance; the point itself is not the center.','使用圓心到所給點的距離；所給點不是圓心。'));
 if(k===4)return eq('Find the parameter range for a real nondegenerate circle.','求表示實非退化圓的參數範圍。',`x^2+y^2-${2*t}x+4y+\\lambda=0`,`\\lambda<${t*t+4}`,C,'r²=t²+4−λ',[`(x-${t})^2+(y+2)^2=${t*t+4}-\\lambda`,`r^2>0`],p('The zero-radius boundary is a point rather than a circle.','零半徑邊界是單點，不是圓。'));
 if(k===5)return eq('Find the circle through O=(0,0), A=(2t,0), B=(0,2).','求通過 O=(0,0)、A=(2t,0)、B=(0,2) 的圓。',`t=${t}`,`x^2+y^2-${2*t}x-2y=0`,A,'F=0;\\quad D=-2t;\\quad E=-2',[`${4*t*t}+${2*t}D=0\\Rightarrow D=-${2*t}`,'4+2E=0\\Rightarrow E=-2'],p('Three noncollinear points determine one circle.','三個不共線點決定唯一的圓。'));
 return n('The circle center is (t,0), radius 2. Find the largest x-coordinate on it.','圓心為 (t,0)，半徑為2。求圓上最大的 x 座標。',`t=${t}`,t+2,A,'|x-t|\\le2',[`x_{\\max}=${t}+2=${t+2}`],p('The extremal point lies on the horizontal diameter.','極值點在水平直徑上。'));
});

add(meta('s1-2-5',p('Relations between lines and circles','直線與圓、圓與圓的位置關係'),91,p('Classify intersection and tangency using distances, discriminants and common chords.','用距離、判別式及公共弦分類相交與相切關係。'),[
 c('Line-circle relation','直線與圓的關係','Compare center-to-line distance with radius; a secant chord has half-length √(r²−d²).','比較圓心到直線的距離與半徑；割線的半弦長為 √(r²−d²)。'),
 c('Circle-circle conditions','兩圓條件','Compare center distance with r1+r2 and |r1−r2|; equal centers require separate treatment.','比較圓心距與 r1+r2 及 |r1−r2|；同心圓須另行處理。')
],[p('Equal center distance and radius difference is internal tangency only for distinct centers and positive radii.','只有相異圓心及正半徑時，圓心距等於半徑差才表示內切。')],['s1-2-4'],probe('How many intersection points remain when a secant is moved away from the circle?','割線逐漸移離圓心時，交點個數怎樣改變？','Explain the same transition using distance and a quadratic discriminant.','分別用距離及二次式判別式解釋同一轉變。')),(k,t)=>{
 if(k===0)return n('Find the number of common points.','求公共點個數。',`x^2+y^2=${t*t},\\quad y=${t}`,1,A,'d=r',[`d=${t}=r\\Rightarrow\\text{tangent}`],p('Equality gives one tangent point.','距離等於半徑時有一個切點。'));
 if(k===1)return n('Find the length of the chord.','求弦長。',`x^2+y^2=25,\\quad y=3`,8,A,'L=2\\sqrt{r^2-d^2}',['L=2\\sqrt{25-9}=8'],p('The perpendicular from the center bisects the chord.','圓心到弦的垂線平分此弦。'));
 if(k===2)return n('Find the tangent length from P to the circle.','求 P 到圓的切線長。',`P=(${t+2},0),\\quad x^2+y^2=4`,Math.sqrt((t+2)**2-4),A,'PT^2=OP^2-r^2',[`PT=\\sqrt{${(t+2)**2}-4}`],p('The external point, tangent point and center form a right triangle.','外點、切點及圓心形成直角三角形。'));
 if(k===3)return eq('Classify the relation of these two circles.','分類這兩個圓的位置關係。',`C_1:x^2+y^2=${t*t}, C_2:(x-${t+3})^2+y^2=9`,`d=r_1+r_2=${t+3}`,A,'d=r1+r2',[`d=${t+3}=r_1+r_2`],p('The circles are externally tangent.','兩圓外切。'));
 if(k===4)return eq('Find the radical axis and state when it is a common chord line.','求根軸，並說明何時它是公共弦所在直線。',`x^2+y^2=25,\\quad(x-${t})^2+y^2=25`,`x=${t/2}`,A,'Subtract the equations.',[`-2(${t})x+${t*t}=0`,`x=${t}/2`],p(`The center distance is ${t}. ${t<10?'There are two common points, so this is their chord line.':t===10?'The circles are tangent, so there is no nonzero common chord.':'The circles are disjoint, so the radical axis is not a common chord line.'}`,`圓心距為 ${t}。${t<10?'有兩個公共點，因此此線是公共弦所在直線。':t===10?'兩圓相切，沒有非零公共弦。':'兩圓相離，因此根軸不是公共弦所在直線。'}`));
 if(k===5)return eq('Find the tangent at the given point.','求在所給點的切線。',`x^2+y^2=${25*t*t}, P=(${3*t},${4*t})`,`3x+4y=${25*t}`,A,'The radius is normal to the tangent.',[`3(x-${3*t})+4(y-${4*t})=0`,`3x+4y=${25*t}`],p('The point is on the circle and fixes the tangent constant.','所給點在圓上，並決定切線常數。'));
 return eq('Find all values of a for which y=a is tangent to x²+y²=t².','求使 y=a 與圓 x²+y²=t² 相切的所有 a。',`t=${t}`,`a=\\pm${t}`,A,'d=|a|=r',[`|a|=${t}\\Rightarrow a=\\pm${t}`],p('Both the upper and lower horizontal tangents must be retained.','須保留上方及下方兩條水平切線。'));
});

add(meta('s1-3-1',p('Ellipse','橢圓'),105,p('Use the focal definition, standard equation and geometric properties of an ellipse.','運用橢圓的焦點定義、標準方程及幾何性質。'),[
 c('Focal sum','焦距和','Distances to the two foci sum to 2a; c²=a²−b².','到兩焦點的距離和為2a；c²=a²−b²。','x^2/a^2+y^2/b^2=1'),
 c('Axis conditions','軸的條件','For a horizontal major axis a>b>0; the larger denominator specifies the major axis.','水平長軸時 a>b>0；較大的分母指定長軸方向。')
],[p('The letter attached to x² is not always the major semiaxis.','x² 下的分母不一定是長半軸平方。')],['s1-2-4'],probe('Predict the ellipse shape and eccentricity as b approaches a or zero.','預測 b 接近 a 或零時，橢圓形狀及離心率怎樣變化。','Compare the limiting geometry with the conditions for a nondegenerate ellipse.','比較極限圖形與非退化橢圓的條件。')),(k,t)=>{
 const a=t+2,b=t,c0=Math.sqrt(a*a-b*b);
 if(k===0)return n('Find the major-axis length.','求長軸長。',`x^2/${a*a}+y^2/${b*b}=1`,2*a,A,'\\text{major axis}=2a',[`2a=2(${a})=${2*a}`],p('An axis is twice the corresponding semiaxis.','軸長是對應半軸長的兩倍。'));
 if(k===1)return n('Find the squared focal distance c².','求 c²。',`a=${a},\\quad b=${b}`,a*a-b*b,A,'c^2=a^2-b^2',[`c^2=${a*a}-${b*b}=${a*a-b*b}`],p('For an ellipse, subtract the squared semiaxes.','橢圓的 c² 為兩半軸平方之差。'));
 if(k===2)return n('Find the eccentricity.','求離心率。',`x^2/${a*a}+y^2/${b*b}=1`,c0/a,A,'e=c/a',[`c=\\sqrt{${a*a-b*b}}`,`e=\\sqrt{${a*a-b*b}}/${a}`],p('A noncircular nondegenerate ellipse has 0<e<1.','非圓且非退化的橢圓有 0<e<1。'));
 if(k===3)return n('P is on the ellipse and PF1=t. Find PF2.','P 在橢圓上，PF1=t。求 PF2。',`a=${a},\\quad PF_1=${t}`,2*a-t,A,'PF_1+PF_2=2a',[`PF_2=${2*a}-${t}=${2*a-t}`],p('The distance-sum definition avoids solving coordinates.','距離和定義可避免求點的座標。'));
 if(k===4)return eq('Find the horizontal ellipse with a=t+1 and c=t.','求 a=t+1、c=t 的水平長軸橢圓。',`t=${t}`,`x^2/${(t+1)**2}+y^2/${2*t+1}=1`,A,'b²=a²−c²',[`b^2=${(t+1)**2}-${t*t}=${2*t+1}`],p('The positive difference guarantees a nondegenerate ellipse.','正的平方差保證為非退化橢圓。'));
 if(k===5)return n('Find the length of the chord cut by x=0.','求 x=0 截得的弦長。',`x^2/${a*a}+y^2/${b*b}=1`,2*b,A,'y^2/b^2=1',[`y=\\pm${b}\\Rightarrow L=${2*b}`],p('The chord through the center along the y-axis is the minor axis.','沿 y 軸通過圓心的弦為短軸。'));
 return n('Find the largest value of 3x+4y on the ellipse.','求此橢圓上 3x+4y 的最大值。',`x^2/${a*a}+y^2/${b*b}=1`,Math.sqrt(9*a*a+16*b*b),A,'x=a cos u, y=b sin u',[`3x+4y=${3*a}\\cos u+${4*b}\\sin u`,`\\max=\\sqrt{${9*a*a+16*b*b}}`],p('The full trigonometric range attains the amplitude.','完整三角參數範圍可達到振幅最大值。'));
});

add(meta('s1-3-2',p('Hyperbola','雙曲線'),118,p('Use the distance-difference definition, asymptotes and branch restrictions.','運用距離差定義、漸近線及分支限制。'),[
 c('Parameters','參數','For x²/a²−y²/b²=1, c²=a²+b² and asymptotes are y=±(b/a)x.','對水平雙曲線，c²=a²+b²，漸近線為 y=±(b/a)x。'),
 c('Branch conditions','分支條件','a,b>0 and e>1; a distance difference is absolute, and an asymptote is not part of the curve.','a、b>0 且 e>1；距離差取絕對值，漸近線不屬於雙曲線。')
],[p('Using c²=a²−b² confuses a hyperbola with an ellipse.','使用 c²=a²−b² 是把雙曲線與橢圓混淆。')],['s1-3-1'],probe('Can a line have one intersection with a hyperbola without being a tangent?','直線與雙曲線只有一個交點時，必定相切嗎？','Compare a tangent with a line parallel to an asymptote and explain the reduced equation.','比較切線與平行於漸近線的直線，解釋消元後方程降次。')),(k,t)=>{
 const a=t,b=2;
 if(k===0)return n('Find c².','求 c²。',`x^2/${a*a}-y^2/4=1`,a*a+4,A,'c^2=a^2+b^2',[`c^2=${a*a}+4=${a*a+4}`],p('The focal square is a sum for a hyperbola.','雙曲線的焦點參數平方為半軸平方之和。'));
 if(k===1)return n('Find the length of the transverse axis.','求實軸長。',`x^2/${a*a}-y^2/4=1`,2*a,A,'\\text{transverse axis}=2a',[`2a=${2*a}`],p('Only the positive squared term specifies the transverse axis.','正的平方項指定實軸方向。'));
 if(k===2)return n('Find the positive asymptote slope.','求正斜率漸近線的斜率。',`x^2/${a*a}-y^2/4=1`,2/a,A,'x^2/a^2-y^2/b^2=0',[`y=\\pm(2/${a})x`],p('The asymptotes come from the homogeneous quadratic part.','漸近線由齊次二次部分得到。'));
 if(k===3)return n('Find the eccentricity.','求離心率。',`a=${a},\\quad b=2`,Math.sqrt(a*a+4)/a,A,'e=c/a',[`e=\\sqrt{${a*a+4}}/${a}`],p('The computed value must exceed one.','計算結果必須大於一。'));
 if(k===4)return eq('Find the horizontal hyperbola with vertices (±t,0) and foci (±(t+2),0).','求頂點 (±t,0)、焦點 (±(t+2),0) 的水平雙曲線。',`t=${t}`,`x^2/${t*t}-y^2/${4*t+4}=1`,A,'b²=c²−a²',[`b^2=${(t+2)**2}-${t*t}=${4*t+4}`],p('For a hyperbola c exceeds a.','雙曲線的 c 大於 a。'));
 if(k===5)return eq('Find the intersection with x=0.','求與 x=0 的交點。',`x^2/${a*a}-y^2/4=1`,'\\varnothing',A,'-y^2/4=1',['y^2=-4'],p('No real point can have a negative square; the conjugate-axis line does not meet this hyperbola.','實數平方不能為負；共軛軸所在直線不與此雙曲線相交。'));
 return eq('Show there is one common point and explain why this line is not tangent.','證明只有一個公共點，並說明此線不是切線。',`y=x+${t}, x^2-y^2=${t*t}`,`P=(-${t},0)`,A,'Substitution cancels the quadratic terms.',[`-${2*t}x-${t*t}=${t*t} ⇒ x=-${t}, y=0`,`\\text{tangent at }P:x=-${t}`],p('The line is parallel to an asymptote; one intersection can result from degree reduction.','此線平行於漸近線；消元降次亦可導致一個交點。'));
});

add(meta('s1-3-3',p('Parabola','拋物線'),130,p('Relate focus, directrix and vertex, and retain conditions in line-parabola intersections.','連結焦點、準線及頂點，並在直線與拋物線相交時保留條件。'),[
 c('Focus-directrix','焦點準線','y²=4ax has focus (a,0) and directrix x=−a.','y²=4ax 的焦點為 (a,0)，準線為 x=−a。'),
 c('Nondegeneracy','非退化條件','a must be nonzero; a parabola has a vertex and no center of symmetry.','a 須非零；拋物線有頂點，沒有對稱中心。')
],[p('For y²=2px the focal coordinate is p/2, not p.','對 y²=2px，焦點橫座標為 p/2，不是 p。')],['s1-3-2'],probe('How does changing the sign of a alter y²=4ax?','改變 a 的正負會怎樣改變 y²=4ax？','Translate a parabola and distinguish its vertex from a nonexistent symmetry center.','平移一條拋物線，區分其頂點與不存在的對稱中心。')),(k,t)=>{
 if(k===0)return n('Find the x-coordinate of the focus.','求焦點的 x 座標。',`y^2=${4*t}x`,t,A,'4a=4t',[`a=${t}\\Rightarrow F=(${t},0)`],p('Read the focal parameter after matching the coefficient 4a.','先把係數對應為4a，再讀取焦點參數。'));
 if(k===1)return n('Find the x-coordinate of the directrix.','求準線的 x 座標。',`y^2=${4*t}x`,-t,A,'\\text{directrix}:x=-a',[`x=-${t}`],p('Focus and directrix are on opposite sides of the vertex.','焦點及準線位於頂點兩側。'));
 if(k===2)return eq('Find the parabola with vertex O and focus (0,−t).','求頂點為 O、焦點為 (0,−t) 的拋物線。',`t=${t}`,`x^2=-${4*t}y`,A,'x^2=4ay,\\quad a=-t',[`x^2=4(-${t})y`],p('The focus below the vertex gives a downward opening.','焦點在頂點下方，拋物線向下開口。'));
 if(k===3)return n('On y²=4tx, P has x-coordinate 2t. Find PF.','在 y²=4tx 上，P 的 x 座標為2t。求 PF。',`t=${t}`,3*t,A,'PF=\\operatorname{dist}(P,x=-t)',[`PF=|${2*t}+${t}|=${3*t}`],p('Use equal distance to focus and directrix without solving y.','利用到焦點及準線距離相等，無須求 y。'));
 if(k===4)return n('Find the length of the focal chord perpendicular to the axis.','求垂直於對稱軸的焦弦長。',`y^2=${4*t}x`,4*t,A,'x=a\\Rightarrow y^2=4a^2',[`y=\\pm2(${t})\\Rightarrow L=${4*t}`],p('The latus rectum has length 4|a|.','正焦弦長為4|a|。'));
 if(k===5)return eq('Find the tangent of slope 1 to y²=4tx.','求斜率為1且與 y²=4tx 相切的直線。',`t=${t}`,`y=x+${t}`,A,'y=x+b\\Rightarrow x^2+(2b-4t)x+b^2=0',[`\\Delta=(2b-${4*t})^2-4b^2=${16*t}(${t}-b)`,`\\Delta=0\\Rightarrow b=${t}`],p('The quadratic coefficient remains nonzero, so a repeated root establishes tangency.','二次項係數不為零，因此重根可確定相切。'));
 return eq('Find all k giving exactly one common point.','求使公共點恰有一個的所有 k。',`y^2=${4*t}x, y=kx+${2*t}`,'k=0\\quad\\text{or}\\quad k=1/2',A,'Handle k=0 before using a discriminant.',[`k=0 ⇒ y=${2*t}, x=${t}`,`k≠0: \\Delta=${16*t*t}(1-2k)`,`\\Delta=0 ⇒ k=1/2`],p('The horizontal case is transverse; the second case is tangent.','水平線情況為橫截；另一情況才是相切。'));
});

const M=(id,en,zh,page,focusEn,focusZh,formula,conditionEn,conditionZh,errorEn,errorZh,prerequisites,predictEn,predictZh,transferEn,transferZh)=>meta(id,p(en,zh),page,p(focusEn,focusZh),[
 c('Defining relation','定義關係',focusEn,focusZh,formula),c('Conditions','適用條件',conditionEn,conditionZh)
],[p(errorEn,errorZh)],prerequisites,probe(predictEn,predictZh,transferEn,transferZh));
const SE=p('Express the indexed terms or partial sums before simplifying.','先表示各項或部分和，再作化簡。');
const AP=p('Use the common difference and the arithmetic-sum formula.','使用公差及等差數列求和公式。');
const GP=p('Use the common ratio and check its special cases.','使用公比，並檢查特殊情況。');
const I=p('Verify the base case, assume the claim at k, and prove it at k+1.','驗證起始情況，假設 k 時成立，再證明 k+1 時成立。');
const DF=p('Differentiate the specified function and substitute only after differentiating.','先對指定函數求導，再代入指定值。');

add(M('s2-4-1','Concept of a sequence','數列的概念',2,'Connect general terms, recurrence relations and partial sums.','連結通項、遞推關係及部分和。','a_n=S_n-S_{n-1}\\ (n\\ge2)','Indices are positive integers; a1=S1 needs separate treatment.','下標為正整數；a1=S1 須獨立處理。','Using S0 from a formula stated only for n≥1 can give a wrong first term.','把只對 n≥1 成立的公式延伸到 S0，可能得到錯誤首項。',[], 'Does a partial-sum formula automatically work at n=0?','部分和公式必定能用於 n=0 嗎？','Compare the first term with terms found by successive differences.','比較首項及用相鄰部分和之差求得的其他項。'),(k,t)=>{
 if(k===0)return n('Find a3.','求 a3。',`a_n=${t}n+1`,3*t+1,SE,'a_3=3t+1',[`a_3=${t}\\cdot3+1=${3*t+1}`],p('The index is substituted in every occurrence of n.','下標須代入每個 n 的位置。'));
 if(k===1)return n('Find a4 from the recurrence.','由遞推式求 a4。',`a_1=2,\\quad a_{n+1}=a_n+${t}`,2+3*t,SE,'a_4=a_1+3t',[`a_2=${2+t},\\ a_3=${2+2*t},\\ a_4=${2+3*t}`],p('Three transitions lead from index 1 to index 4.','從下標1到4須作三次遞推。'));
 if(k===2)return n('Find a1.','求 a1。',`S_n=n^2+${t}\\quad(n\\ge1)`,1+t,SE,'a_1=S_1',[`a_1=1^2+${t}=${1+t}`],p('The formula was not given at n=0; subtracting its extrapolated S0 would lose the constant.','公式未指定 n=0；減去外推的 S0 會錯誤消去常數。'));
 if(k===3)return n('Find a5.','求 a5。',`S_n=${t}n^2+1\\quad(n\\ge1)`,9*t,SE,'a_5=S_5-S_4',[`a_5=(${25*t}+1)-(${16*t}+1)=${9*t}`],p('For n≥2 the constants cancel in successive differences.','n≥2 時，相鄰部分和之差會消去常數。'));
 if(k===4)return n('Find the smallest positive index with an>t.','求使 an>t 的最小正整數下標。',`a_n=2n-1,\\quad t=${t}`,Math.floor((t+1)/2)+1,SE,'2n-1>t',[`n>${(t+1)/2}`,`n_{\\min}=${Math.floor((t+1)/2)+1}`],p('A strict inequality and an integer index require the next larger integer.','嚴格不等式及整數下標要求取下一個較大整數。'));
 if(k===5)return n('Find the sum of the first t terms.','求前 t 項和。',`a_n=\\frac1{n(n+1)},\\quad t=${t}`,t/(t+1),SE,'1/[n(n+1)]=1/n-1/(n+1)',[`S_t=(1-1/2)+(1/2-1/3)+\\cdots+(1/${t}-1/${t+1})`,`S_t=1-1/${t+1}=${t}/${t+1}`],p('Retain the two boundary terms after telescoping.','裂項相消後須保留兩個邊界項。'));
 return eq('Prove that the sequence is strictly increasing.','證明此數列嚴格遞增。',`a_n=1-\\frac{${t}}{n+1},\\quad n\\ge1`,'a_{n+1}-a_n>0',SE,'Compare consecutive terms.',[`a_{n+1}-a_n=${t}/[(n+1)(n+2)]>0`],p('Positive denominators and t>0 establish monotonicity for every allowed index.','分母及 t 均為正，故所有允許下標均有遞增性。'));
});

add(M('s2-4-2','Arithmetic sequences','等差數列',12,'Derive terms and sums and solve indexed arithmetic models.','推導等差數列的項與和，解決含下標的等差模型。','a_n=a_1+(n-1)d;\\quad S_n=n(a_1+a_n)/2','A finite sum contains n terms, hence n−1 differences.','n 項的有限和只有 n−1 個相鄰公差。','A middle-term identity depends on the number of terms being odd.','中項公式取決於項數為奇數。',['s2-4-1'],'How does the sign of the common difference affect the largest partial sum?','公差的正負怎樣影響最大部分和？','Construct a sequence whose terms cross zero and locate its maximum partial sum.','構造項值穿過零的数列，找出最大部分和。'),(k,t)=>{
 if(k===0)return n('Find a6.','求 a6。',`a_1=${t},\\quad d=3`,t+15,AP,'a_6=a_1+5d',[`a_6=${t}+15=${t+15}`],p('The sixth term is five differences after the first.','第六項在首項後有五個公差。'));
 if(k===1)return n('Find the common difference.','求公差。',`a_2=${t},\\quad a_5=${t+12}`,4,AP,'a_5-a_2=3d',[`3d=12\\Rightarrow d=4`],p('Index distance, not the larger index, counts the differences.','公差次數由下標差決定，不是由較大的下標決定。'));
 if(k===2)return n('Find S4.','求 S4。',`a_1=${t},\\quad d=2`,4*t+12,AP,'S_4=4[2a_1+3d]/2',[`S_4=2(${2*t}+6)=${4*t+12}`],p('Average the first and last term, then multiply by the number of terms.','先求首末項平均，再乘以項數。'));
 if(k===3)return n('Find a5 when S9 is given.','已知 S9，求 a5。',`S_9=${9*t}`,t,AP,'S_9=9a_5',[`a_5=${9*t}/9=${t}`],p('With nine terms, the fifth is the middle term.','九項時第五項為中項。'));
 if(k===4)return n('How many terms of 2,5,8,… are at most 3t+2?','2、5、8、… 中，有多少項不大於3t+2？',`t=${t}`,t+1,AP,'2+3(n-1)\\le3t+2',[`n\\le${t+1}\\Rightarrow N=${t+1}`],p('The inclusive endpoint is counted.','等於上界的最後一項須計入。'));
 if(k===5)return n('Find the sum of all positive terms in t,t−1,t−2,… .','求 t、t−1、t−2、… 中所有正數項之和。',`t=${t}`,t*(t+1)/2,AP,'t+(t-1)+\\cdots+1',[`N=${t}`,`S=${t}(${t}+1)/2=${t*(t+1)/2}`],p('Zero does not add to the sum, and negative terms would decrease it.','零不增加部分和，負項則會減少部分和。'));
 return n('A theatre has t rows; the first has 10 seats and each next row has 2 more. Find the total seats.','戲院有 t 排；首排10個座位，每後一排多2個。求總座位數。',`t=${t}`,t*(t+9),AP,'a_t=10+2(t-1)',[`a_t=${2*t+8}`,`S_t=${t}(10+${2*t+8})/2=${t*(t+9)}`],p('The discrete row count is positive and integral; no continuous rounding is needed.','排數為正整數，不需作連續模型的四捨五入。'));
});

add(M('s2-4-3','Geometric sequences','等比數列',27,'Connect ratios, indexed powers and finite geometric sums.','連結公比、下標次方及有限等比和。','a_n=a_1q^{n-1};\\quad S_n=a_1(1-q^n)/(1-q)','The geometric ratio is defined for nonzero terms; q=1 uses Sn=na1.','等比數列公比以非零項定義；q=1 時使用 Sn=na1。','The sum formula with denominator 1−q cannot be used directly at q=1.','分母為1−q 的求和公式不能直接用於 q=1。',['s2-4-1'],'Does a negative ratio imply a decreasing sequence?','公比為負是否代表數列遞減？','Compare term signs and partial sums for positive and negative ratios.','比較正負公比下的項值符號及部分和。'),(k,t)=>{
 if(k===0)return n('Find a4.','求 a4。',`a_1=${t},\\quad q=2`,8*t,GP,'a_4=a_1q^3',[`a_4=${t}\\cdot8=${8*t}`],p('Use n−1 in the exponent.','指數使用 n−1。'));
 if(k===1)return n('Find q.','求公比 q。',`a_2=${t},\\quad a_3=-${2*t}`,-2,GP,'q=a_3/a_2',['q=-2'],p('The sign of the ratio controls alternating signs.','公比的正負控制各項是否交替正負。'));
 if(k===2)return n('Find S3.','求 S3。',`a_1=${t},\\quad q=3`,13*t,GP,'S_3=a_1(1+q+q^2)',[`S_3=${t}(1+3+9)=${13*t}`],p('Direct expansion is an independent check on the finite-sum formula.','直接逐項相加可獨立檢查有限和公式。'));
 if(k===3)return n('Find S5 when q=1.','公比 q=1 時，求 S5。',`a_1=${t}`,5*t,GP,'S_5=5a_1',[`S_5=5(${t})=${5*t}`],p('All terms are equal; the quotient formula would have zero denominator.','各項相等；商式求和公式的分母會為零。'));
 if(k===4)return n('Find a3a7 given a5=t.','已知 a5=t，求 a3a7。',`t=${t}`,t*t,GP,'a_3a_7=a_5^2',[`a_3a_7=a_1^2q^8=a_5^2=${t*t}`],p('Equal index sums give equal products in a nonzero geometric sequence.','非零等比數列中，下標和相同的兩項乘積相同。'));
 if(k===5)return eq('Find all real geometric means between t and 4t.','求 t 與4t 之間所有實數等比中項。',`t=${t}`,`b=\\pm${2*t}`,GP,'b^2=ac',[`b^2=${t}\\cdot${4*t}=${4*t*t}`,`b=\\pm${2*t}`],p('Without a positivity condition, both signs are possible.','未限制中項為正時，正負兩值均可能。'));
 return n('A geometric sequence has S2=t and S4=5t. Find q².','等比數列有 S2=t、S4=5t。求 q²。',`t=${t}`,4,GP,'S_4=S_2(1+q^2)',['5=1+q^2','q^2=4'],p('Divide by the known nonzero S2; the equation determines q² rather than the sign of q.','因 S2 非零可相除；方程只確定 q²，未確定 q 的正負。'));
});

add(M('s2-4-4','Mathematical induction','數學歸納法',44,'Build proofs with a verified base, an explicit induction hypothesis and a valid step.','用已驗證的起點、明確歸納假設及有效歸納步驟建立證明。','P(n_0)\\land[P(k)\\Rightarrow P(k+1)]','Induction proves a statement only for the specified integer domain starting at the base case.','歸納法只證明從起點開始、指定整數範圍內的命題。','Checking many examples does not establish the induction step.','驗算很多例子不能代替歸納步驟。',['s2-4-2','s2-4-3'],'Can a correct induction step rescue a false or missing base case?','正確的歸納步驟能補救錯誤或缺漏的起始情況嗎？','Identify the failed link in a proposed proof and repair the domain or argument.','指出一份擬議證明中失敗的環節，修正範圍或論證。'),(k,t)=>{
 if(k===0)return eq('Prove the shifted-integer sum by induction.','用歸納法證明平移整數求和式。',`\\sum_{j=1}^n(j+${t})=n(${t})+n(n+1)/2`,`S_n=${t}n+n(n+1)/2`,I,'S(k+1)=S(k)+k+1+t',[`n=1:1+${t}=${t}+1`,`S_{k+1}=${t}k+k(k+1)/2+k+1+${t}`,`S_{k+1}=${t}(k+1)+(k+1)(k+2)/2`],p('The next shifted term includes the fixed constant.','新增的平移項須包含固定常數。'));
 if(k===1)return eq('Prove the odd-number sum identity.','證明奇數求和公式。','1+3+\\cdots+(2n-1)=n^2','S_n=n^2',I,'S_{k+1}=S_k+2k+1',['n=1:\\ 1=1','S_{k+1}=k^2+2k+1=(k+1)^2'],p('The newly added odd term is 2k+1, not 2k−1.','新增的奇數項是2k+1，不是2k−1。'));
 if(k===2)return eq('Prove the finite power-of-two identity.','證明有限二次冪求和公式。','1+2+\\cdots+2^{n-1}=2^n-1','S_n=2^n-1',I,'S_{k+1}=S_k+2^k',['n=1:\\ 1=2-1','S_{k+1}=2^k-1+2^k=2^{k+1}-1'],p('At n terms the highest exponent is n−1.','n 項和的最高指數是 n−1。'));
 if(k===3)return eq('Prove n³−n+3tn is divisible by 3 for all n≥1.','證明所有 n≥1，n³−n+3tn 可被3整除。',`t=${t}`,'3 | (n³−n+3tn)',I,'f(k+1)−f(k)=3k(k+1)+3t',[`f(1)=3(${t})`,`f(k+1)=f(k)+3k(k+1)+3(${t})`],p('Both the base and the increment are multiples of three.','起始值及增量均為3的倍數。'));
 if(k===4)return eq('Prove 2ⁿ≥n+1 for every integer n≥t, using t as the base.','以 t 為起點，證明所有整數 n≥t，2ⁿ≥n+1。',`t=${t}`,`2^n\\ge n+1\\quad(n\\ge${t})`,I,'2^(k+1)=2·2^k',[`n=${t}:2^{${t}}=${2**t}≥${t+1}`,`2^{k+1}≥2(k+1)≥k+2`],p('The explicit base check and the induction step cover only the stated domain.','明確起始驗證及歸納步驟只涵蓋指定範圍。'));
 if(k===5)return eq('Prove the scaled telescoping identity by induction.','用歸納法證明此縮放裂項公式。',`\\sum_{j=1}^n${t}/[j(j+1)]=${t}n/(n+1)`,`S_n=${t}n/(n+1)`,I,'S(k+1)=S(k)+t/[(k+1)(k+2)]',[`n=1:${t}/2=${t}/2`,`S_{k+1}=${t}k/(k+1)+${t}/[(k+1)(k+2)]=${t}(k+1)/(k+2)`],p('The constant factor remains in the added term and target.','固定因子须保留在新增項及目標式。'));
 return eq('Disprove the claim that n²+n+t is prime for every nonnegative integer n.','反證所有非負整數 n，n²+n+t 都是質數的命題。',`t=${t}`,`n=${t}:n^2+n+t=${t}·${t+2}`,p('Find one valid counterexample.','找一個符合範圍的反例。'),'Try n=t.',[`n=${t} ⇒ n^2+n+t=${t}(${t+2})`],p('Both factors exceed one, so the expression is composite.','兩因子均大於一，因此此值為合數。'));
});

add(M('s2-5-1','Derivative: concept and meaning','導數的概念及其意義',59,'Distinguish average and instantaneous rates and derive tangents from a limit.','區分平均與瞬時變化率，從極限推導切線。','f\\prime(a)=\\lim_{h\\to0}[f(a+h)-f(a)]/h','The difference quotient uses h≠0; differentiability requires a finite common two-sided limit.','差商要求 h≠0；可微要求左右極限相同且有限。','Continuity alone does not imply differentiability.','連續本身不能保證可微。',['c1-3-1'],'Does a graph without a jump always have a tangent slope?','没有跳躍的圖形必定有切線斜率嗎？','Compare a smooth point with a corner by left and right quotients.','用左右差商比較光滑點及尖角。'),(k,t)=>{
 if(k===0)return n('Find the derivative of x² at x=t from the limit.','由極限求 x² 在 x=t 的導數。',`t=${t}`,2*t,DF,'[(t+h)^2-t^2]/h=2t+h',[`f'(${t})=\\lim_{h\\to0}(${2*t}+h)=${2*t}`],p('Cancel h only while h≠0, then take the limit.','只有 h≠0 時才約去 h，再求極限。'));
 if(k===1)return n('Find the average rate of x² from t to t+1.','求 x² 從 t 到 t+1 的平均變化率。',`t=${t}`,2*t+1,DF,'[f(t+1)-f(t)]/1',[`(${t+1})^2-${t}^2=${2*t+1}`],p('A secant rate over a finite interval is not generally the endpoint derivative.','有限區間的割線變化率通常不是端點的導數。'));
 if(k===2)return n('Position is s(u)=u²+3u. Find velocity at u=t.','位置 s(u)=u²+3u。求 u=t 時速度。',`t=${t}`,2*t+3,DF,'v(u)=s\\prime(u)=2u+3',[`v(${t})=${2*t+3}`],p('Velocity has position-units per time-unit; acceleration would require another derivative.','速度單位是位置單位除以時間單位；加速度須再求一次導數。'));
 if(k===3)return eq('Find the tangent to y=x² at x=t.','求 y=x² 在 x=t 的切線。',`t=${t}`,`y-${t*t}=${2*t}(x-${t})`,DF,'m=f\\prime(t),\\quad P=(t,t^2)',[`m=${2*t}`,`y-${t*t}=${2*t}(x-${t})`],p('A slope alone is not a line equation; include the point of contact.','斜率本身不是直線方程；須包含切點。'));
 if(k===4)return eq('Is |x−t| differentiable at x=t?','|x−t| 在 x=t 可微嗎？',`t=${t}`,`f\\prime(${t})\\text{ undefined}`,p('Compare the left and right difference quotients.','比較左右差商。'),'|h|/h',['h>0: |h|/h=1','h<0: |h|/h=−1'],p('Continuity does not remove the mismatch in the one-sided derivatives.','連續不能消除左右導數不相同的問題。'));
 if(k===5)return n('A tank volume V(h)=3h². Find dV/dh at h=t.','水箱體積 V(h)=3h²。求 h=t 時 dV/dh。',`t=${t}`,6*t,DF,'dV/dh=6h',[`V'(${t})=${6*t}`],p('The derivative is volume change per height change, not necessarily volume change per time.','此導數是體積對高度的變化率，不一定是對時間的變化率。'));
 return eq('Find the normal to y=x² at x=t.','求 y=x² 在 x=t 的法線。',`t=${t}`,`y-${t*t}=-\\frac1{${2*t}}(x-${t})`,DF,'m_{\\rm normal}=-1/f\\prime(t)',[`m_{\\rm tangent}=${2*t}\\ne0`,`m_{\\rm normal}=-1/${2*t}`],p('The given derivative is nonzero; a zero tangent slope would require a vertical normal.','此題導數非零；若切線斜率為零，法線應為鉛直線。'));
});

add(M('s2-5-2','Derivative operations','導數的運算',72,'Apply power, product, quotient and chain rules with elementary derivatives.','配合基本函數導數，運用冪、乘積、商及鏈式法則。','(uv)\\prime=u\\prime v+uv\\prime;\\quad [f(g)]\\prime=f\\prime(g)g\\prime','Quotient denominators stay nonzero; logarithms have positive real arguments and trigonometric derivatives use radians.','商的分母須非零；實對數的真數須為正，三角函數求導使用弧度。','The derivative of a product is not the product of the derivatives.','乘積的導數不是各導數的乘積。',['s2-5-1'],'Which rule is needed before substituting a point into a composite function?','複合函數在代入點之前須用哪個法則？','Compare a correct chain rule with a calculation missing the inner derivative.','比較正確鏈式法則與漏掉內層導數的計算。'),(k,t)=>{
 if(k===0)return n('Find f′(1).','求 f′(1)。',`f(x)=x^3+${t}x`,3+t,DF,'f\\prime(x)=3x^2+t',[`f'(1)=3+${t}=${3+t}`],p('Differentiate term by term.','逐項求導。'));
 if(k===1)return n('Find f′(1) using the product rule.','用乘積法則求 f′(1)。',`f(x)=x^2(x+${t})`,3+2*t,DF,'f\\prime=2x(x+t)+x^2',[`f'(1)=2(1+${t})+1=${3+2*t}`],p('Both factors contribute to the derivative.','兩個因子均對導數有貢獻。'));
 if(k===2)return n('Find f′(0).','求 f′(0)。',`f(x)=\\frac{x+${t}}{x+1}`,1-t,DF,'f\\prime=[(x+1)-(x+t)]/(x+1)^2',[`f'(x)=(1-${t})/(x+1)^2`,`f'(0)=${1-t}`],p('The domain excludes x=−1, and zero is admissible.','定義域排除 x=−1；零可代入。'));
 if(k===3)return n('Find f′(0) using the chain rule.','用鏈式法則求 f′(0)。',`f(x)=(2x+${t})^3`,6*t*t,DF,'f\\prime=3(2x+t)^2\\cdot2',[`f'(0)=6(${t})^2=${6*t*t}`],p('The inner derivative contributes a factor of two.','內層導數提供因子2。'));
 if(k===4)return n('Find f′(0).','求 f′(0)。',`f(x)=e^{${t}x}`,t,DF,'f\\prime(x)=te^{tx}',[`f'(0)=${t}e^0=${t}`],p('The natural exponential reproduces itself under differentiation.','自然指數函數求導後仍保留本身。'));
 if(k===5)return n('Find f′(1).','求 f′(1)。',`f(x)=\\ln(${t}x)`,1,DF,'f\\prime(x)=t/(tx)=1/x',['f\\prime(1)=1'],p('The scale inside the logarithm cancels, but the real domain remains x>0.','對數內的比例因子約去，但實數定義域仍為 x>0。'));
 return n('Find f′(0), using radians.','使用弧度，求 f′(0)。',`f(x)=\\sin(${t}x)+\\cos x`,t,DF,'f\\prime(x)=t\\cos(tx)-\\sin x',[`f'(0)=${t}\\cdot1-0=${t}`],p('A radian argument is essential for the familiar sine derivative formula.','常用正弦導數公式必須使用弧度。'));
});

add(M('s2-5-3','Applications of derivatives','導數在研究函數中的應用',84,'Use derivative signs, boundary values and models to justify extrema and optimization.','用導數符號、邊界值及模型，說明極值與最佳化。','f\\prime>0\\Rightarrow f\\text{ increasing}','A critical point needs a sign or second-derivative check; closed-interval global extrema also require endpoints.','駐點須檢查符號或二階導數；閉區間全域極值亦須比較端點。','A zero derivative alone does not imply a maximum or minimum.','導數為零本身不表示最大或最小。',['s2-5-2'],'Can a stationary point fail to be an extremum?','駐點可能不是極值點嗎？','Compare x² and x³ at zero and explain their derivative sign changes.','比較 x²、x³ 在零的情況，解釋導數符號變化。'),(k,t)=>{
 if(k===0)return n('Find the minimizing x over all real x.','求在所有實數 x 中使函數最小的 x。',`f(x)=x^2-${2*t}x+1`,t,DF,'f\\prime(x)=2x-2t',[`f'(x)=0\\Rightarrow x=${t}`,`f''(x)=2>0`],p('A positive quadratic has a unique global minimum.','正首項二次函數有唯一全域最小值。'));
 if(k===1)return n('Find the maximum of f on [0,t].','求 f 在 [0,t] 的最大值。',`f(x)=x^2,\\quad t=${t}`,t*t,DF,'f\\prime(x)=2x\\ge0',[`f(0)=0,\\quad f(${t})=${t*t}`],p('Compare the endpoints of the closed interval.','比較閉區間兩個端點。'));
 if(k===2)return eq('Find the increasing and decreasing intervals.','求遞增及遞減區間。',`f(x)=x^2-${2*t}x`, `(-\\infty,${t}):\\searrow;\\quad(${t},\\infty):\\nearrow`,DF,'f\\prime(x)=2(x-t)',[`x<${t}:f'<0;\\quad x>${t}:f'>0`],p('The derivative sign changes from negative to positive.','導數符號由負轉正。'));
 if(k===3)return eq('Is x=t a local extremum of (x−t)³?','x=t 是 (x−t)³ 的局部極值點嗎？',`t=${t}`,'stationary inflection; no local extremum',DF,'f\\prime(x)=3(x-t)^2',[`f\\prime(x)>0\\quad(x\\ne${t})`],p('The derivative has the same sign on both sides.','兩側導數具有相同正負號。'));
 if(k===4)return n('A rectangle has perimeter 4t. Find its maximum area.','矩形周長為4t。求最大面積。',`t=${t}`,t*t,DF,'y=2t-x;\\quad A=x(2t-x)',[`A'=${2*t}-2x=0\\Rightarrow x=${t}`,`A_{\\max}=${t*t}`],p('The domain 0<x<2t admits the square, and boundary areas approach zero.','定義域 0<x<2t 包含正方形；邊界面積趨近零。'));
 if(k===5)return n('Find the minimum of x+t²/x for x>0.','x>0 時，求 x+t²/x 的最小值。',`t=${t}`,2*t,DF,'f\\prime(x)=1-t^2/x^2',[`f'=0\\Rightarrow x=${t}`,`f''=${2*t*t}/x^3>0`, `f(${t})=${2*t}`],p('The negative critical solution is outside the positive domain.','負的駐點解不在正數定義域內。'));
 return n('Profit is P(x)=−x²+2tx−3, for 0≤x≤t+2. Find maximum profit.','利潤 P(x)=−x²+2tx−3，0≤x≤t+2。求最大利潤。',`t=${t}`,t*t-3,DF,'P\\prime(x)=2t-2x',[`x=${t}\\text{ lies in the domain}`,`P(${t})=${t*t-3}`,`P''=-2<0`],p('The feasible vertex gives the optimum; the model concerns profit, not gross revenue.','可行頂點給出最佳利潤；此模型不是總收入。'));
});

const CT=p('Decide whether choices are alternative cases or successive stages, then check overlap.','判斷選擇屬互斥分類或連續步驟，再檢查重複計數。');
const PR=p('Express the event with a conditional probability or a disjoint partition.','以條件概率或互斥分割表示事件。');
const RV=p('List the possible values and probabilities before computing moments.','先列出可能值及概率，再計算數字特徵。');
const ST=p('Use the paired-data summaries, preserving which observations belong together.','使用配對數據摘要，保留各觀察值之間的配對。');

add(M('s3-6-1','Addition and multiplication counting principles','分類加法與分步乘法計數原理',2,'Count disjoint alternatives and sequential choices without overlap or omission.','對互斥分類及連續選擇作計數，避免重複或漏算。','N=\\sum N_i\\quad\\text{or}\\quad N=\\prod N_i','Addition requires disjoint cases; stage counts must hold for each branch or use separate branches.','加法要求分類互斥；步驟數須對各分支成立，否則須分開計算。','Having two choices to describe does not automatically mean multiply.','描述了兩種選擇，不代表必定相乘。',[],'When should two counts be added rather than multiplied?','何時應把兩個數量相加，而不是相乘？','Draw a branching tree with unequal numbers of second-stage choices.','繪製第二步選擇數不相等的分支樹。'),(k,t)=>{
 if(k===0)return n('Choose one book: t mathematics titles or 3 history titles, with no overlap. How many choices?','選一本書：有 t 本數學及3本歷史，沒有重複。共有多少選擇？',`t=${t}`,t+3,CT,'N=t+3',[`N=${t}+3=${t+3}`],p('The two subject cases are disjoint alternatives.','兩個學科分類是互斥的替代選擇。'));
 if(k===1)return n('Choose one of t shirts and one of 4 trousers. How many outfits?','從 t 件上衣及4條褲，各選一件。共有多少套搭配？',`t=${t}`,4*t,CT,'N=t\\cdot4',[`N=${4*t}`],p('Every shirt permits all four trouser choices.','每件上衣都容許四種褲子的選擇。'));
 if(k===2)return n('A code is one of t letters followed by a digit 0–9. How many codes?','代碼由 t 個字母之一及其後一個0–9數字組成。共有多少代碼？',`t=${t}`,10*t,CT,'N=t\\cdot10',[`N=${10*t}`],p('A leading-zero restriction does not apply to the second symbol in this code.','此代碼第二個符號沒有首位數字不可為零的限制。'));
 if(k===3)return n('Among t+8 students, t study art, 8 study music and 3 study both. How many study either subject?','t+8 名學生中，t 人學美術、8人學音樂、3人兩者都學。多少人至少學一科？',`t=${Math.max(t,3)}`,Math.max(t,3)+5,CT,'|A\\cup B|=|A|+|B|-|A\\cap B|',[`N=${Math.max(t,3)}+8-3=${Math.max(t,3)+5}`],p('Subtract the overlap once because it was counted twice.','交集被計入兩次，所以減去一次。'));
 if(k===4)return n('There are t first-stage choices with 2 continuations each, and 3 other choices with 5 continuations each. Count paths.','第一步有 t 個選擇各接2條路，另有3個選擇各接5條路。求總路徑數。',`t=${t}`,2*t+15,CT,'N=2t+3\\cdot5',[`N=${2*t}+15=${2*t+15}`],p('Unequal branch sizes require addition of branch products.','分支大小不相等，須把各分支乘積相加。'));
 if(k===5)return n('Passwords of length 3 use t symbols with repetition allowed. Exclude those with all symbols identical. Count remaining passwords.','三位密碼使用 t 個符號，可重複。排除三位完全相同的密碼後，有多少？',`t=${t}`,t**3-t,CT,'N=t^3-t',[`N=${t**3}-${t}=${t**3-t}`],p('The excluded all-identical passwords are one per symbol, not one total.','每個符號各有一個全相同密碼，不是總共只有一個。'));
 return n('Use digits 0,…,t−1 to form two-digit numbers without repeated digits, where 2≤t≤9. Count them.','用0至t−1組成不重複數字的兩位數，2≤t≤9。共有多少？',`t=${2+t%7}`,(1+t%7)**2,CT,'(t-1)(t-1)',[`\\text{first choices}=${1+t%7}`,`\\text{second choices}=${1+t%7}`,`N=${(1+t%7)**2}`],p('The first digit cannot be zero; the second may be zero but cannot repeat the first.','首位不能為零；第二位可為零，但不能重複首位。'));
});

add(M('s3-6-2','Permutations and combinations','排列與組合',14,'Distinguish ordered selections, unordered sets and symmetry in arrangements.','區分有序選取、無序集合及排列中的對稱性。','P_n^r=n!/(n-r)!;\\quad C_n^r=n!/[r!(n-r)!]','Counts use nonnegative integer sizes; decide whether labels, order and rotations distinguish outcomes.','人數及項數為非負整數；須判斷標籤、次序及旋轉是否構成不同結果。','Dividing by r! is valid only when every selected set has exactly r! counted orders.','只有每個選取集合均被計為 r! 種次序時，才可除以 r!。',['s3-6-1'],'Why does choosing a committee differ from choosing president and secretary?','選委員會為甚麼與選主席及秘書不同？','Compare labeled assignments and identical objects in a small exhaustive list.','用小型完整列表比較有標籤分配及相同物件。'),(k,t)=>{
 const m=5+t%11;
 if(k===0)return n('Choose a president and secretary from m distinct people. Count assignments.','從 m 個不同的人中選主席及秘書。求分配數。',`m=${m}`,m*(m-1),CT,'P_m^2=m(m-1)',[`N=${m}(${m}-1)=${m*(m-1)}`],p('The two offices are different, so order matters.','兩個職位不同，因此次序重要。'));
 if(k===1)return n('Choose an unordered committee of 3 from m people.','從 m 人中選沒有次序的三人委員會。',`m=${m}`,choose(m,3),CT,'C_m^3=P_m^3/3!', [`N=${m}(${m-1})(${m-2})/6=${choose(m,3)}`],p('Each committee was counted in six possible orders.','每個委員會曾被計為六種次序。'));
 if(k===2)return n('Arrange m distinct people in a circle, considering rotations identical but reflections different.','m 個不同的人圍圓桌而坐，旋轉視為相同，鏡射視為不同。共有多少坐法？',`m=${m}`,factorial(m-1),CT,'N=(m-1)!',[`N=${factorial(m-1)}`],p('Fix one person to remove rotational duplicates.','固定一人以消除旋轉重複。'));
 if(k===3){const r=2+t%4;return n('Count arrangements containing r identical As, two identical Bs and one C.','求含 r 個相同 A、兩個相同 B 及一個 C 的不同排列數。',`r=${r}`,((r+1)*(r+2)*(r+3))/2,CT,'(r+3)!/(r!2!)',[`N=${r+3}!/(${r}!2!)=${((r+1)*(r+2)*(r+3))/2}`],p('Permutations of each identical-letter group do not create new arrangements.','每組相同字母內部交換不會產生新排列。'));}
 if(k===4)return n('From m people, form a 3-person committee that includes a specified person.','從 m 人選三人委員會，須包含指定的一人。共有多少選法？',`m=${m}`,choose(m-1,2),CT,'C_{m-1}^2',[`N=C_{${m-1}}^2=${choose(m-1,2)}`],p('Select only the remaining two members from the other people.','只須從其餘人中選另外兩位成員。'));
 if(k===5)return n('Place t identical balls in 3 labeled boxes; empty boxes are allowed. Count distributions.','把 t 個相同球放入3個有標籤的盒，可有空盒。共有多少分法？',`t=${t}`,choose(t+2,2),CT,'x_1+x_2+x_3=t,\\quad x_i\\ge0',[`N=C_{${t+2}}^2=${choose(t+2,2)}`],p('Stars and bars count integer allocations; labeled boxes remain distinct.','隔板法計算整數分配；有標籤的盒仍須區分。'));
 return n('Arrange m distinct people in a line with A and B adjacent.','m 個不同的人排成一列，A、B 必須相鄰。共有多少排法？',`m=${m}`,2*factorial(m-1),CT,'Treat A,B as one block.',[`N=2(m-1)!=${2*factorial(m-1)}`],p('Multiply by two for AB and BA inside the block.','把區塊內 AB、BA 的兩種次序乘入。'));
});

add(M('s3-6-3','Binomial theorem','二項式定理',29,'Use the general term to locate coefficients, constants and coefficient sums.','用通項找出係數、常數項及係數和。','(a+b)^n=\\sum_{r=0}^nC_n^ra^{n-r}b^r','The exponent n is a nonnegative integer; term number is r+1, not r.','指數 n 為非負整數；第幾項為 r+1，不是 r。','A binomial coefficient and the full coefficient of a term may differ.','二項式係數與某項的完整係數可能不同。',['s3-6-2'],'Does a negative second term change all coefficients to negative?','第二項為負，是否所有展開係數都為負？','Use parity of the selection index to explain the sign pattern.','用所選下標的奇偶解釋正負模式。'),(k,t)=>{
 const m=4+t%11;
 if(k===0)return n('Find the coefficient of x in (1+x)^m.','求 (1+x)^m 中 x 的係數。',`m=${m}`,m,CT,'C_m^1=m',[`[x](1+x)^{${m}}=${m}`],p('Selecting x from exactly one factor gives the coefficient.','從恰好一個因子選出 x 得到此係數。'));
 if(k===1)return n('Find the coefficient of x² in (1+x)^m.','求 (1+x)^m 中 x² 的係數。',`m=${m}`,choose(m,2),CT,'C_m^2=m(m-1)/2',[`[x^2]=${choose(m,2)}`],p('The unordered pair of chosen factors determines the term.','所選兩個因子的無序組合決定此項。'));
 if(k===2)return n('Find the sum of all coefficients of (2+x)^m.','求 (2+x)^m 的所有係數之和。',`m=${m}`,3**m,CT,'Substitute x=1.',[`(2+1)^{${m}}=${3**m}`],p('Use x=1 for the full coefficient sum, not 2^m unless both base coefficients equal one.','完整係數和用 x=1；只有兩個基本係數都是一時才為2^m。'));
 if(k===3)return n('Find the coefficient of x² in (1−2x)^m.','求 (1−2x)^m 中 x² 的係數。',`m=${m}`,4*choose(m,2),CT,'C_m^2(-2)^2',[`[x^2]=4C_{${m}}^2=${4*choose(m,2)}`],p('An even selection index makes this coefficient positive.','選取下標為偶數，因此此係數為正。'));
 if(k===4)return n('Find the constant term in (x+1/x)^2m.','求 (x+1/x)^2m 的常數項。',`m=${m}`,choose(2*m,m),CT,'x^{2m-r}x^{-r}=x^{2m-2r}',[`${2*m}-2r=0\\Rightarrow r=${m}`,`T=C_{${2*m}}^{${m}}=${choose(2*m,m)}`],p('A zero exponent locates the constant term; then evaluate its coefficient.','先令指數為零找出常數項，再計算係數。'));
 if(k===5)return n('Find the alternating sum of binomial coefficients for m≥1.','m≥1 時，求二項式係數的交替和。',`\\sum_{r=0}^{${m}}(-1)^rC_{${m}}^r`,0,CT,'Substitute x=-1 in (1+x)^m.',[`(1-1)^{${m}}=0`],p('The exponent is positive, so the substitution is unambiguous.','指數為正，因此此代入沒有歧義。'));
 return n('Find the remainder when (1+10)^m is divided by 100.','求 (1+10)^m 除以100的餘數。',`m=${m}`,(1+10*m)%100,CT,'Terms with r≥2 contain 100.',[`11^{${m}}\\equiv1+10(${m})\\pmod{100}`,`R=${(1+10*m)%100}`],p('Reduce the surviving expression modulo 100; it may still exceed 99.','保留式子仍可大於99，須再取除以100的餘數。'));
});

add(M('s3-7-1','Conditional and total probability','條件概率與全概率公式',44,'Use conditional denominators, disjoint partitions and Bayes inversion.','使用條件分母、互斥分割及貝葉斯反向推論。','P(A|B)=P(A\\cap B)/P(B)','The conditioning event must have positive probability; a total-probability partition is exhaustive and disjoint.','條件事件概率須為正；全概率分割須互斥且涵蓋全部樣本。','P(A|B) need not equal P(B|A), and independence differs from mutual exclusivity.','P(A|B) 不一定等於 P(B|A)；獨立與互斥不同。',['s3-6-2'],'Can two events be independent even when both may occur together?','兩事件可同時發生時，仍可能獨立嗎？','Construct a probability table showing independence and compare its two conditional directions.','構造顯示獨立的概率表，並比較兩個條件方向。'),(k,t)=>{
 const u=t+4;
 if(k===0)return n('Find P(A|B) from the given probabilities.','由已知概率求 P(A|B)。',`P(A\\cap B)=1/${u},\\quad P(B)=2/${u}`,0.5,PR,'P(A|B)=P(A\\cap B)/P(B)',['P(A|B)=(1/u)/(2/u)=1/2'],p('Restrict the sample space to B.','把樣本空間限制到 B。'));
 if(k===1)return n('From a bag of t red and 2 blue balls, two are drawn without replacement. Given the first is red, find the probability the second is blue.','袋有 t 個紅球及2個藍球，不放回抽兩球。已知首球紅色，求第二球藍色的概率。',`t=${t}`,2/(t+1),PR,'After a red draw, total=t+1 and blue=2.',[`P=2/${t+1}`],p('The color count and denominator must reflect the information already given.','顏色數及分母須反映已知資訊。'));
 if(k===2)return n('Events A,B are independent with P(A)=1/3 and P(B)=t/(t+1). Find P(A∩B).','A、B 獨立，P(A)=1/3、P(B)=t/(t+1)。求 P(A∩B)。',`t=${t}`,t/(3*(t+1)),PR,'P(A\\cap B)=P(A)P(B)',[`P=${t}/[3(${t+1})]`],p('Multiplication here is justified by the stated independence.','此處相乘由已指定的獨立性支持。'));
 if(k===3)return n('Choose machine 1 with probability 1/(t+2) and machine 2 otherwise. Failure rates are 1/10 and 1/5. Find total failure probability.','以1/(t+2)概率選機器1，否則選機器2；失敗率分別為1/10及1/5。求總失敗概率。',`t=${t}`,(2*t+3)/(10*(t+2)),PR,'P(F)=P(M_1)P(F|M_1)+P(M_2)P(F|M_2)',[`P(F)=\\frac1{${t+2}}\\frac1{10}+\\frac{${t+1}}{${t+2}}\\frac15=\\frac{${2*t+3}}{${10*(t+2)}}`],p('The machine cases form a disjoint exhaustive partition.','機器選擇構成互斥且完備的分割。'));
 if(k===4)return n('Choose machine 1 with probability 1/(t+2), otherwise machine 2; their failure rates are 1/10 and 1/5. Given failure, find P(machine 1).','以1/(t+2)概率選機器1，否則選機器2；失敗率為1/10及1/5。已知失敗，求使用機器1的概率。',`t=${t}`,1/(2*t+3),PR,'P(M_1|F)=P(M_1\\cap F)/P(F)',[`P(F)=${2*t+3}/[10(${t+2})]`,`P(M_1|F)=\\frac{1/[10(${t+2})]}{${2*t+3}/[10(${t+2})]}=1/${2*t+3}`],p('The posterior denominator includes failures from both machines.','後驗概率的分母包含兩台機器的失敗情況。'));
 if(k===5)return eq('A and B are disjoint and both have positive probability. Can they be independent?','A、B 互斥且兩者概率都為正。它們可獨立嗎？',`P(A)=1/${u},\\quad P(B)=1/${u}`,'P(A\\cap B)=0\\ne P(A)P(B)',PR,'Compare the intersection with the product.',[`P(A)P(B)=1/${u*u}>0`],p('Disjoint positive-probability events are dependent.','概率均為正的互斥事件並不獨立。'));
 return n('A fair coin selects a bag: bag 1 has t red and 1 blue; bag 2 has 1 red and t blue. Given a red draw, find the probability bag 1 was chosen.','公平硬幣選袋：袋1有 t 紅1藍；袋2有1紅 t 藍。已知抽到紅球，求選袋1的概率。',`t=${t}`,t/(t+1),PR,'Use Bayes with P(red)=1/2.',[`P(R)=\\tfrac12[t/(${t+1})+1/(${t+1})]=1/2`,`P(B_1|R)=t/${t+1}`],p('Equal bag-selection priors do not remain equal after observing the color.','觀察顏色後，原本相等的選袋先驗概率不再相等。'));
});

add(M('s3-7-2','Discrete random variables and distributions','離散型隨機變量及其分佈列',56,'Construct a distribution and compute event probabilities from its support.','建立分佈列，從可能值集合計算事件概率。','\\sum_xP(X=x)=1','Every probability lies in [0,1]; values and events must not be double-counted.','每個概率均在 [0,1]；取值及事件不能重複計數。','A random variable value and its probability are not interchangeable.','隨機變量取值與其概率不能互換。',['s3-7-1'],'Can two different outcomes lead to the same random-variable value?','兩個不同樣本結果能對應同一隨機變量值嗎？','Group outcomes by their value before adding probabilities.','先按取值合併樣本結果，再把概率相加。'),(k,t)=>{
 if(k===0)return n('Find the missing probability p.','求缺少的概率 p。',`X\\in\\{0,${t},${t+1}\\};\\quad P=(1/4,p,1/2)`,0.25,RV,'1/4+p+1/2=1',['p=1/4'],p('Normalisation determines the remaining probability.','概率總和為一決定剩餘概率。'));
 if(k===1)return n('Find P(X≥t).','求 P(X≥t)。',`X\\in\\{0,${t},${t+1}\\};\\quad P=(1/4,1/4,1/2)`,0.75,RV,'Add probabilities at t and t+1.',['P(X\\ge t)=1/4+1/2=3/4'],p('The threshold selects values, then their probabilities are added.','先按門檻選取值，再加上其概率。'));
 if(k===2){const r=2+t%4;return n('Toss r independent fair coins; X counts heads. Find P(X=1).','拋 r 枚獨立公平硬幣，X 為正面數。求 P(X=1)。',`r=${r}`,r/2**r,RV,'Group the equally likely outcomes with one head.',[`P(X=1)=${r}/${2**r}`],p('There is one favorable outcome for each possible position of the sole head.','唯一正面每個可能位置，各對應一個符合條件的結果。'));}
 if(k===3)return eq('Give the distribution of Y=2X+1.','寫出 Y=2X+1 的分佈列。',`X=0,${t};\\quad P=1/3,2/3`,`Y=1,${2*t+1};\\quad P=1/3,2/3`,RV,'Map each support value through Y=2X+1.',[`0\\mapsto1,\\quad ${t}\\mapsto${2*t+1}`],p('An injective value transformation keeps the corresponding probabilities.','一對一取值變換保留對應概率。'));
 if(k===4)return n('Find p when P(X=0)=p, P(X=1)=2p and P(X=2)=tp.','P(X=0)=p、P(X=1)=2p、P(X=2)=tp，求 p。',`t=${t}`,1/(t+3),RV,'p+2p+tp=1',[`${t+3}p=1\\Rightarrow p=1/${t+3}`],p('Check all resulting probabilities are nonnegative.','須檢查所有結果概率均非負。'));
 if(k===5)return eq('Can these numbers be a probability distribution? Explain.','這些數字可構成概率分佈嗎？說明。',`X=0,${t},${t+1};\\quad P=0.6,0.5,-0.1`,'\\text{invalid}',RV,'Check nonnegativity as well as the total.',['0.6+0.5-0.1=1','P(X=t+1)=-0.1<0'],p('A sum of one alone is insufficient.','總和為一並不足夠。'));
 return n('A fair die is rolled; X=1 for a face at most d, and X=0 otherwise. Find P(X=0).','擲公平骰子；點數不大於 d 時 X=1，否則 X=0。求 P(X=0)。',`d=${1+t%6}`,(5-t%6)/6,RV,'Count faces strictly above d.',[`P(X=0)=(6-${1+t%6})/6=${5-t%6}/6`],p('Different die faces are grouped into one binary value.','不同骰子點數被合併為一個二元取值。'));
});

add(M('s3-7-3','Numerical characteristics of random variables','離散型隨機變量的數字特徵',62,'Compute expectation and variance and distinguish transformation from random independence.','計算期望及方差，區分取值變換與隨機獨立性。','E(X)=\\sum xp_x;\\quad\\operatorname{Var}(X)=E(X^2)-[E(X)]^2','Variance is nonnegative; variance of a sum includes covariance unless independence is justified.','方差非負；求和的方差須包含協方差，除非有獨立性支持。','E(X²) is generally not [E(X)]².','E(X²) 通常不等於 [E(X)]²。',['s3-7-2'],'Does doubling all outcomes double or quadruple the variance?','把所有取值加倍，方差會加倍還是變成四倍？','Compare X, 2X and X+constant from the same distribution.','由同一分佈比較 X、2X 及 X 加常數。'),(k,t)=>{
 if(k===0)return n('Find E(X).','求 E(X)。',`X=0,${t};\\quad P=1/2,1/2`,t/2,RV,'E(X)=0/2+t/2',[`E(X)=${t}/2`],p('Expectation is a weighted average, not necessarily a possible outcome.','期望是加權平均，不一定是可能取值。'));
 if(k===1)return n('Find E(X²).','求 E(X²)。',`X=0,${t};\\quad P=1/2,1/2`,t*t/2,RV,'Square the outcomes before averaging.',[`E(X^2)=0/2+${t*t}/2`],p('Square outcomes before averaging; do not square the expectation instead.','先把取值平方再平均；不要改成把期望平方。'));
 if(k===2)return n('Find Var(X).','求 Var(X)。',`X=0,${t};\\quad P=1/2,1/2`,t*t/4,RV,'Var(X)=E(X^2)-E(X)^2',[`Var(X)=${t*t}/2-(${t}/2)^2=${t*t}/4`],p('The variance has squared outcome units.','方差的單位為取值單位的平方。'));
 if(k===3)return n('Find E(3X+2).','求 E(3X+2)。',`E(X)=${t}`,3*t+2,RV,'E(aX+b)=aE(X)+b',[`E(3X+2)=3(${t})+2=${3*t+2}`],p('Linearity of expectation does not require independence.','期望的線性性不需要獨立性。'));
 if(k===4)return n('Find Var(3X+2).','求 Var(3X+2)。',`Var(X)=${t}`,9*t,RV,'Var(aX+b)=a^2Var(X)',[`Var(3X+2)=9(${t})=${9*t}`],p('A constant shift has no effect on variance.','平移常數不影響方差。'));
 if(k===5)return n('Independent X,Y have variances t and 2. Find Var(X+Y).','獨立 X、Y 的方差為 t 及2。求 Var(X+Y)。',`t=${t}`,t+2,RV,'Var(X+Y)=Var(X)+Var(Y)',[`Var(X+Y)=${t}+2=${t+2}`],p('Independence supplies zero covariance here.','此處獨立性使協方差為零。'));
 return n('A game pays t with probability 1/4 and 0 otherwise; entry fee is 2. Find expected net gain.','遊戲以1/4概率派發 t，否則為0；入場費為2。求預期淨收益。',`t=${t}`,t/4-2,RV,'Net gain=payment-2.',[`E(G)=${t}/4-2=${t/4-2}`],p('Expected net gain differs from the gross expected payment and is not a guaranteed outcome.','預期淨收益不同於預期總派發額，也不是保證獲得的結果。'));
});

add(M('s3-7-4','Binomial and hypergeometric distributions','二項分佈與超幾何分佈',72,'Choose the correct model for repeated independent trials or sampling without replacement.','為重複獨立試驗或不放回抽樣選擇正確模型。','P(X=k)=C_n^kp^k(1-p)^{n-k}','Binomial trials have fixed n, common p and independence; hypergeometric sampling uses a finite population without replacement.','二項試驗有固定 n、相同 p 及獨立性；超幾何抽樣使用有限母體且不放回。','Sampling without replacement is not generally binomial.','不放回抽樣通常不是二項分佈。',['s3-7-3'],'Which probability changes after one success is removed from a finite bag?','有限袋中移除一個成功物件後，哪個概率會改變？','Compare with-replacement and without-replacement models using the same bag.','用同一袋比較放回及不放回模型。'),(k,t)=>{
 const m=3+t%11;
 if(k===0)return n('X~Bin(m,1/2). Find P(X=0).','X~Bin(m,1/2)。求 P(X=0)。',`m=${m}`,2**(-m),PR,'P(X=0)=(1-p)^m',[`P(X=0)=2^{-${m}}`],p('Zero successes requires failure in every independent trial.','零次成功要求每次獨立試驗均失敗。'));
 if(k===1)return n('X~Bin(m,1/2). Find P(X=1).','X~Bin(m,1/2)。求 P(X=1)。',`m=${m}`,m/2**m,PR,'P(X=1)=C_m^1/2^m',[`P(X=1)=${m}/${2**m}`],p('There are m possible locations of the single success.','恰好一次成功可出現在 m 個位置。'));
 if(k===2)return n('X~Bin(m,1/4). Find E(X).','X~Bin(m,1/4)。求 E(X)。',`m=${m}`,m/4,RV,'E(X)=mp',[`E(X)=${m}/4`],p('Expectation counts the mean number of successes.','期望表示平均成功次數。'));
 if(k===3)return n('X~Bin(m,1/4). Find Var(X).','X~Bin(m,1/4)。求 Var(X)。',`m=${m}`,3*m/16,RV,'Var(X)=mp(1-p)',[`Var(X)=${m}(1/4)(3/4)=${3*m}/16`],p('Include the failure probability as well as the success probability.','須同時包含失敗概率及成功概率。'));
 if(k===4)return n('A bag has t red and 3 blue balls; select 2 without replacement. Find the probability both are blue.','袋有 t 紅3藍；不放回選2球。求兩球均藍的概率。',`t=${t}`,3/choose(t+3,2),PR,'C_3^2/C_{t+3}^2',[`P=3/${choose(t+3,2)}`],p('The unordered sample denominator counts pairs, not independent trials.','無序樣本的分母計算二球組合，不是獨立試驗。'));
 if(k===5)return n('From t red and 3 blue balls, select 2 without replacement. Find the probability exactly one is red.','從 t 紅3藍不放回選2球。求恰有一紅的概率。',`t=${t}`,3*t/choose(t+3,2),PR,'C_t^1C_3^1/C_{t+3}^2',[`P=${3*t}/${choose(t+3,2)}`],p('Choose one from each color; do not add a spurious ordering factor.','每種顏色各選一球；不要額外乘上次序因子。'));
 return n('Independent trials succeed with probability 1/2. Find the least n for success at least once with probability ≥1−2^(−m).','獨立試驗的成功概率為1/2。求使至少一次成功概率≥1−2^(−m) 的最小 n。',`m=${m}`,m,PR,'1-2^{-n}\\ge1-2^{-m}',[`2^{-n}\\le2^{-${m}}\\Rightarrow n\\ge${m}`],p('Use the complementary event of no successes.','使用一次都沒有成功的補事件。'));
});

add(M('s3-7-5','Normal distribution','正態分佈',83,'Standardise a normal variable and interpret supplied table probabilities and symmetry.','把正態變量標準化，解釋所提供的表概率及對稱性。','Z=(X-\\mu)/\\sigma','σ>0; probability table values are supplied in each task. A continuous variable has zero probability at a single point.','σ>0；各題提供所需概率表值。連續變量在單點的概率為零。','The second parameter in N(μ,σ²) is variance, not standard deviation.','N(μ,σ²) 第二參數為方差，不是標準差。',['s3-7-3'],'Does shifting the mean change the probability within one standard deviation?','平移平均數會改變落在一個標準差內的概率嗎？','Compare the same standardised interval in two different normal models.','比較兩個正態模型中相同的標準化區間。'),(k,t)=>{
 if(k===0)return n('X~N(t,4). Find its standard deviation.','X~N(t,4)。求標準差。',`t=${t}`,2,RV,'\\sigma=\\sqrt{\\sigma^2}',['\\sigma=\\sqrt4=2'],p('The variance 4 has square root 2.','方差4的平方根為2。'));
 if(k===1)return n('Standardise x=t+4 under X~N(t,4). Find z.','在 X~N(t,4) 下，把 x=t+4 標準化，求 z。',`t=${t}`,2,RV,'z=(x-\\mu)/\\sigma',[`z=(${t+4}-${t})/2=2`],p('Divide by standard deviation, not variance.','除以標準差，不是方差。'));
 if(k===2)return n('X~N(t,4), Φ(1)=0.8413. Find P(X≤t+2).','X~N(t,4)，Φ(1)=0.8413。求 P(X≤t+2)。',`t=${t}`,0.8413,PR,'(t+2-t)/2=1',['P(X\\le\\mu+\\sigma)=\\Phi(1)=0.8413'],p('The requested bound is one standard deviation above the mean.','所求上界在平均數以上一個標準差。'));
 if(k===3)return n('X~N(t,4), Φ(1)=0.8413. Find P(t−2≤X≤t+2).','X~N(t,4)，Φ(1)=0.8413。求 P(t−2≤X≤t+2)。',`t=${t}`,0.6826,PR,'\\Phi(-1)=1-\\Phi(1)',['P(-1\\le Z\\le1)=2\\Phi(1)-1=0.6826'],p('Subtract the lower tail rather than adding two cumulative probabilities.','須減去左尾，不是把兩個累積概率相加。'));
 if(k===4)return n('X~N(t,9), Φ(2)=0.9772. Find P(X>t+6).','X~N(t,9)，Φ(2)=0.9772。求 P(X>t+6)。',`t=${t}`,0.0228,PR,'z=6/3=2',['P(X>\\mu+2\\sigma)=1-\\Phi(2)=0.0228'],p('The requested event is a right tail, not a left cumulative probability.','所求事件為右尾，不是左側累積概率。'));
 if(k===5)return n('X~N(t,4). Find P(X=t).','X~N(t,4)。求 P(X=t)。',`t=${t}`,0,PR,'A continuous distribution assigns zero mass to a point.',['P(X=\\mu)=0'],p('The density is largest at the mean, but point probability is still zero.','平均數處密度最大，但單點概率仍為零。'));
 return eq('Models A~N(t,4), B~N(t+10,9). Compare P(A≤t+2) and P(B≤t+13).','A~N(t,4)、B~N(t+10,9)。比較 P(A≤t+2) 及 P(B≤t+13)。',`t=${t}`,'P(A\\le\\mu_A+\\sigma_A)=P(B\\le\\mu_B+\\sigma_B)',PR,'Standardise each bound.',[`z_A=2/2=1,\\quad z_B=3/3=1`],p('Equal z-scores give equal probabilities despite different units and scales.','即使平均數及尺度不同，相同 z 值仍給出相同概率。'));
});

add(M('s3-8-1','Correlation of paired data','成對數據的統計相關性',93,'Interpret scatter patterns and compute a correlation from centered paired summaries.','解釋散點模式，從中心化配對摘要計算相關係數。','r=S_{xy}/\\sqrt{S_{xx}S_{yy}}','Both centered sums of squares must be positive; correlation measures linear association and does not establish causation.','兩個中心平方和均須為正；相關描述線性關聯，不證明因果。','Zero correlation does not rule out a nonlinear relationship.','相關係數為零不能排除非線性關係。',[],'Can a clear U-shaped relation have zero Pearson correlation?','清楚的 U 形關係可能有零皮爾遜相關嗎？','Compare a symmetric U-shaped scatter with a straight-line scatter.','比較對稱 U 形及直線形的散點圖。'),(k,t)=>{
 if(k===0)return n('Find r from centered summaries.','由中心化摘要求 r。',`S_{xx}=4,\\quad S_{yy}=${t*t},\\quad S_{xy}=${t}`,0.5,ST,'r=S_{xy}/\\sqrt{S_{xx}S_{yy}}',[`r=${t}/(${2*t})=1/2`],p('The positive square root gives the denominator scale.','分母尺度使用正平方根。'));
 if(k===1)return n('Find r when y=tx+2 and x varies.','若 y=tx+2 且 x 並非常數，求 r。',`t=${t}`,1,ST,'S_{xy}=tS_{xx};\\quad S_{yy}=t^2S_{xx}',['r=t/|t|=1'],p('The positive slope gives perfect positive linear correlation.','正斜率給出完全正線性相關。'));
 if(k===2)return n('Find r when y=−tx+2 and x varies.','若 y=−tx+2 且 x 並非常數，求 r。',`t=${t}`,-1,ST,'S_{xy}=-tS_{xx}',['r=-1'],p('Correlation records direction, not just closeness to a line.','相關係數記錄方向，不只是接近直線的程度。'));
 if(k===3)return n('For pairs (−1,t),(0,0),(1,t), find Sxy.','配對數據 (−1,t)、(0,0)、(1,t)，求 Sxy。',`t=${t}`,0,ST,'\\bar x=0;\\quad S_{xy}=\\sum x_i(y_i-\\bar y)',[`S_{xy}=-1(${t}-${2*t}/3)+1(${t}-${2*t}/3)=0`],p('Symmetry cancels the centered products even though the pattern is nonlinear.','即使模式是非線性的，對稱性仍使中心乘積相消。'));
 if(k===4)return eq('Explain whether adding t to all y-values changes r.','說明把所有 y 值加 t 是否改變 r。',`t=${t}`,'r\\text{ unchanged}',ST,'(y_i+t)-(\\bar y+t)=y_i-\\bar y',['S_{xy},S_{yy}\\text{ unchanged}'],p('Correlation is invariant under translation because centered deviations are unchanged.','平移不改變中心偏差，因此不改變相關。'));
 if(k===5)return eq('An observational survey reports the displayed positive correlation between study time and score. Does it prove a causal effect?','觀察調查得出所列讀書時間與分數的正相關。這能證明因果效應嗎？',`r=${(1+t%8)/10}`,'\\text{association does not establish causation}',ST,'Consider confounding and study design.',['\\text{Prior preparation may influence both variables.}'],p('The size of an observational correlation does not replace a causal design or justified control of confounding.','觀察相關的大小不能取代因果設計或合理控制混淆因素。'));
 return eq('Can Pearson r be computed when all x-values equal t? Explain.','全部 x 值均為 t 時，可計算皮爾遜 r 嗎？說明。',`x_i=${t}`,'r\\text{ undefined}',ST,'S_{xx}=0',['r=S_{xy}/\\sqrt{0\\cdot S_{yy}}'],p('A constant variable has no variation against which to measure linear correlation.','常數變量沒有變異，不能用來衡量線性相關。'));
});

add(M('s3-8-2','Linear regression and applications','一元線性回歸模型及其應用',105,'Fit a least-squares line and distinguish prediction, residual and extrapolation.','配適最小二乘直線，區分預測、殘差及外推。','\\hat y=a+bx;\\quad b=S_{xy}/S_{xx};\\quad a=\\bar y-b\\bar x','Sxx>0; extrapolation beyond observed x needs separate justification and predictions are not certain outcomes.','Sxx>0；超出觀察 x 範圍的外推須另作論證，預測不是確定結果。','Residual means observed minus predicted, not the reverse.','殘差為觀察值減預測值，不是相反。',['s3-8-1'],'Must the fitted line pass through every point?','回歸直線必須通過每個數據點嗎？','Compare residuals and the centroid property of a least-squares line.','比較殘差及最小二乘直線通過中心點的性質。'),(k,t)=>{
 if(k===0)return n('Find the fitted slope.','求配適斜率。',`S_{xx}=2,\\quad S_{xy}=${2*t}`,t,ST,'b=S_{xy}/S_{xx}',[`b=${2*t}/2=${t}`],p('The denominator is the variation in the predictor x.','分母為預測變量 x 的變異。'));
 if(k===1)return n('Find the intercept.','求截距。',`\\bar x=2,\\quad\\bar y=${2*t+3},\\quad b=${t}`,3,ST,'a=\\bar y-b\\bar x',[`a=${2*t+3}-2(${t})=3`],p('The fitted line passes through the data centroid.','配適直線通過數據中心點。'));
 if(k===2)return n('Use the fitted line to predict y at x=2.','用配適直線預測 x=2 時的 y。',`\\hat y=3+${t}x`,3+2*t,ST,'\\hat y(2)=3+2t',[`\\hat y=${3+2*t}`],p('This is a fitted prediction rather than the observed response.','這是配適預測值，不是觀察結果。'));
 if(k===3)return n('An observation at x=2 has y=2t+5. Find its residual under ŷ=3+tx.','x=2 時觀察 y=2t+5，回歸式 ŷ=3+tx。求殘差。',`t=${t}`,2,ST,'e=y-\\hat y',[`e=${2*t+5}-(${2*t+3})=2`],p('A positive residual means the observation is above the fitted line.','正殘差表示觀察點在配適直線上方。'));
 if(k===4)return n('For x=−1,0,1 and y=−t,0,t, find the least-squares slope.','x=−1、0、1；y=−t、0、t。求最小二乘斜率。',`t=${t}`,t,ST,'\\bar x=\\bar y=0',[`S_{xx}=2,\\quad S_{xy}=${2*t}`,`b=${t}`],p('Preserve the paired order when calculating products.','計算乘積時須保留配對次序。'));
 if(k===5)return eq('Data were observed only for 0≤x≤t. Assess a prediction at x=10t.','數據只在0≤x≤t內觀察。評估 x=10t 的預測。',`t=${t}`,'\\text{extrapolation requires additional justification}',ST,'Compare the target x with the observed interval.',[`${10*t}>${t}`],p('A good fit inside the sample range does not verify a far-out extrapolation.','樣本範圍內配適良好，不能驗證遠距外推。'));
 return eq('For x=−1,0,1 and y=t,0,t, find the fitted line and explain what it misses.','x=−1、0、1；y=t、0、t。求回歸直線，並解釋其遺漏的模式。',`t=${t}`,`\\hat y=${2*t}/3`,ST,'S_{xy}=0,\\quad \\bar y=2t/3',[`b=0,\\quad a=${2*t}/3`],p('The zero slope misses a U-shaped relation, so inspect the scatter as well as the line.','零斜率遺漏 U 形關係，因此須連同散點图檢視。'));
});

add(M('s3-8-3','Contingency tables and independence tests','列聯表與獨立性檢驗',124,'Compute expected counts and a chi-square statistic and state a bounded conclusion.','計算期望頻數及卡方統計量，並作有界限的結論。','E_{ij}=R_iC_j/N;\\quad\\chi^2=\\sum(O-E)^2/E','Observations must be independent; expected counts support the supplied large-sample approximation. Rejection is evidence of association, not causation.','觀察須獨立；期望頻數須支持所提供的大樣本近似。拒絕獨立只表示關聯證據，不是因果。','Failure to reject does not prove independence.','未拒絕不能證明獨立。',['s3-8-1'],'Can a larger sample increase the statistic when proportions stay fixed?','比例保持固定時，增加樣本量會使統計量變大嗎？','Scale every cell of a 2×2 table and explain the effect on expected counts and χ².','把2×2表各格同比放大，解釋期望頻數及 χ² 的變化。'),(k,t)=>{
 const u=t+10;
 if(k===0)return n('Find the first row total.','求第一列總數。',`O=\\begin{pmatrix}${2*u}&${u}\\\\${u}&${2*u}\\end{pmatrix}`,3*u,ST,'R_1=O_{11}+O_{12}',[`R_1=${2*u}+${u}=${3*u}`],p('Marginal totals sum categories without changing their pairing.','邊際總數合併分類，不改變配對。'));
 if(k===1)return n('Under independence, find E11.','在獨立假設下，求 E11。',`O=\\begin{pmatrix}${2*u}&${u}\\\\${u}&${2*u}\\end{pmatrix}`,1.5*u,ST,'E_{11}=R_1C_1/N',[`E_{11}=(${3*u})^2/${6*u}=${1.5*u}`],p('Use both relevant margins and the full sample size.','使用相關列總數、欄總數及完整樣本量。'));
 if(k===2)return n('Calculate χ² for the table.','計算此表的 χ²。',`O=\\begin{pmatrix}${2*u}&${u}\\\\${u}&${2*u}\\end{pmatrix}`,2*u/3,ST,'All expected cells are 3u/2.',[`\\chi^2=4[(${u}/2)^2/(${3*u}/2)]=${2*u}/3`],p('All four nonnegative cell contributions must be included.','須計入全部四格非負貢獻。'));
 if(k===3)return eq('Use the supplied 5% critical value 3.841 (one degree of freedom) to assess independence.','用所提供的5%臨界值3.841（自由度1），評估獨立性。',`O=\\begin{pmatrix}${2*u}&${u}\\\\${u}&${2*u}\\end{pmatrix}`,'\\text{reject independence at the stated 5% rule}',ST,'\\chi^2=2u/3',[`\\chi^2=${clean(2*u/3)}>3.841`],p('The rule provides evidence of association; it does not estimate a causal effect.','此規則提供關聯證據，不估計因果效應。'));
 if(k===4)return n('Under perfect independence in a table with all four cells t, find χ².','四格均為 t 的完全獨立表，求 χ²。',`t=${u}`,0,ST,'O_{ij}=E_{ij}=t',['\\chi^2=0'],p('Observed counts exactly equal independence expectations.','觀察頻數恰好等於獨立假設期望頻數。'));
 if(k===5)return eq('A before/after category table records the same t people twice. Can a standard independent-observation chi-square analysis treat the records as separate people?','分類前後表把同一批 t 人記錄兩次。一般獨立觀察卡方分析可把兩次記錄當作不同的人嗎？',`t=${u}`,'\\text{the independent-observation assumption fails}',ST,'Check whether rows share participants.', ['\\text{paired records are dependent}'],p('The study needs a method for paired categorical outcomes rather than treating repeated people as independent.','此研究須用配對分類結果的方法，不能把重複記錄的人視為獨立。'));
 return eq('The displayed test statistic is below the supplied 5% threshold 3.841. State the defensible conclusion.','所列統計量低於提供的5%臨界值3.841。寫出合理結論。',`\\chi^2=1+${t}/${t+1}`,'\\text{do not reject independence at this level}',ST,'1<t/(t+1)+1<2<3.841',['\\text{insufficient evidence against independence under the stated model}'],p('Absence of sufficient evidence is not proof of no association; sample power and assumptions still matter.','證據不足不等於證明無關聯；樣本檢定能力及假設仍須考慮。'));
});

export const advancedLessons=entries.map(e=>build(e.meta,e.bank));
export const advancedReviews=advancedChapters.map(ch=>review(ch,entries.filter(e=>e.meta.chapterId===ch.id)));
export { advancedSupplementLessons as advancedSupplements } from './advanced-supplements.mjs';
